      "dossierMd": "■ [E001] 천지창조와 안식일 제정 (Creation & Institution of the Sabbath)\n1. 기본 메타데이터: 고유 ID 및 명칭: E001 / 천지창조와 안식일 제정 (Creation & Sabbath)\n• 히브리어·헬라어 핵심 원어: בָּרָא (bārā’, 오직 하나님만을 주어로 쓰는 '무에서 유를 창조하다'), רוּחַ אֱלֹהִים (rûaḥ ’Ĕlōhîm, 수면 위에 운행하시던 하나님의 영), טוֹב מְאֹד (ṭôḇ mə’ōḏ, \"보시기에 심히 좋았더라\", 창 1:31), שָׁבַת (šāḇaṯ, 쉬다/그치다 → 안식일 Šabbāṯ).\n• 성경 본문 및 병행 성구: 창세기 1:1~2:3 / 시 33:6-9; 104편; 사 45:18; 요 1:1-3(\"만물이 그로 말미암아 지은 바 되었으니\"); 골 1:16; 히 4:3-10; 11:3; 계 4:11.\n• 연결 인물 ID: 삼위일체 하나님(P026 성자 로고스 동참), P001 아담, P002 하와.\n2. 사건 재구성 (6일 창조의 '영역 형성 3일 ↔ 피조물 충만 3일' 대칭 구조): 서언 (창 1:1-2): 태초에 하나님이 천지를 창조하시니라. 땅이 혼돈하고(tōhû) 공허하며(ḇōhû) 흑암이 깊음 위에 있을 때 하나님의 영이 수면 위에 운행하심(암탉이 알을 품듯 생명을 준비하심, 신 32:11 동일 동사 merachephet).\n• 창조 6일의 완벽한 대구(對句) 구조: 영역 형성 (Forming: 혼돈 해결): 피조물 충만 (Filling: 공허 해결) (구속사적 의미)\n• 첫째 날 (1:3-5): 빛(’ôr) 창조, 빛과 어둠 분리(낮과 밤): 넷째 날 (1:14-19): 광명체들(해·달·별)을 만들어 징조와 계절·날·해를 이루게 하심 (고대 근동의 태양신·달신 숭배를 일개 피조물 광명체로 격하!) (그리스도는 참 빛이자 세상의 빛(요 1:9; 8:12; 고후 4:6))\n• 둘째 날 (1:6-8): 궁창(하늘)을 만들어 궁창 위의 물과 아래의 물 분리: 다섯째 날 (1:20-23): 물에 번성하는 물고기와 하늘을 나는 새 창조 및 생육·번성 축복 (생명으로 충만하게 하시는 창조주의 풍성함)\n• 셋째 날 (1:9-13): 뭍(땅)과 바다를 모으시고 채소와 씨 맺는 열매 나무를 내심: 여섯째 날 (1:24-31): 땅의 육축과 짐승, 그리고 하나님의 형상(ṣelem ’Ĕlōhîm)을 따른 사람(남자와 여자) 창조 및 생육·번성·충만·정복·다스림(문화명령, 1:28) (첫 창조의 면류관인 인간 창조와 만물 청지기 위임)\n• 일곱째 날 안식일 제정 (창 2:1-3): 첫째~여섯째 날과 달리 일곱째 날에는 \"저녁이 되고 아침이 되니\"라는 마침 구절이 없음 — 이는 하나님의 영원한 안식에 인간을 초대하시는 열린 날(히 4:3-10)이며, 하나님이 일곱째 날을 복되게 하사 거룩하게 하심(성경에서 최초로 '거룩하다'[qāḏaš]고 선언된 대상은 공간이 아니라 시간[제7일]임!).\n3. 시각 고증 및 시대착오 금지 (E001-S1~S3): S1. 깊음의 수면 위로 첫째 날의 근원적 빛이 폭발하듯 임하는 장면 (창 1:2-3).\n• S2. 여섯째 날 하나님의 형상대로 지음받은 아담과 하와가 보시기에 심히 아름다운 에덴의 온갖 생물 한가운데 서 있는 장면 (창 1:27-31).\n• .",
