      "dossierMd": "■ [E002] 아담과 하와의 창조와 에덴동산 언약 및 첫 혼인 (Eden Covenant & First Marriage)\n1. 기본 메타데이터: 성경 본문: 창세기 2:4-25 / 마 19:4-6; 고전 11:8-9; 15:45; 엡 5:31-32(그리스도와 교회의 비밀) / 연결 인물: P001 아담, P002 하와.\n• 핵심 원어: יָצַר (yāṣar, 토기장이가 흙을 정성껏 빚다, 2:7), נִשְׁמַת חַיִּים (nišmaṯ ḥayyîm, 생령/생기), עָבַד וְשָׁמַר (‘āḇaḏ wəšāmar, 경작하며 지키다 — 후대 성막에서 레위인이 '섬기며 지키다'[민 3:7-8]와 동일한 예배적 동사!), עֵזֶר כְּנֶגְדּוֹ (‘ēzer kəneḡdô, 돕는 배필 — 열등한 보조자가 아니라 '그와 마주 대하여 대등하게 돕는 구원적 동반자').\n2. 사건 전개 및 구속사 핵심: 땅의 흙(아다마)으로 사람(아담)을 지으시고 코에 생기를 불어넣으시니 생령이 됨 → 동방 에덴에 동산을 창설하시고(4대 강: 비손·기혼·힛데겔·유브라데) 동산 중앙에 생명나무와 선악을 알게 하는 나무를 두시며 행위언약(창 2:16-17)을 부여하심(인간을 로봇이 아닌 자유의지와 사랑의 순종 주체로 대우하심) → 아담이 모든 가축과 새에게 이름을 지어 주며 지혜를 발휘했으나 독처하는 것이 좋지 못하여, 아담을 깊이 잠들게 하시고 갈빗대 하나로 여자를 만드사 아담에게로 이끌어 오시니 \"이는 내 뼈 중의 뼈요 살 중의 살이라\" 첫 사랑의 시와 한 몸(bāśār ’eḥāḏ) 혼인 제도가 탄생함.\n3. 대표 장면 시각 고증 (E002-S1~S2): S1. 에덴의 네 강줄기와 생명나무 아래에서 각종 동물들의 이름을 불러 주는 아담 (창 2:19-20).\n• S2. 아침 빛이 비치는 에덴동산에서 하나님이 이끌어 오신 하와의 손을 맞잡고 기뻐하는 아담의 첫 혼인 장면 (창 2:22-24).",
