      "dossierMd": "■ [E003] 선악과 불순종(인류 타락)과 원시복음(창 3:15) 및 가죽옷 은총 (The Fall & Protoevangelium)\n1. 기본 메타데이터: 성경 본문: 창세기 3:1-24 / 롬 5:12-21; 고후 11:3; 딤전 2:13-14; 요일 2:16; 계 12:9; 20:2 / 연결 인물: P001 아담, P002 하와, P026 예수 그리스도(여자의 후손).\n• 핵심 원어: אַף כִּי (’ap̄ kî, \"참으로... 하시더냐?\" — 말씀의 은혜를 축소·왜곡하는 사탄의 첫 질문, 3:1), עִמָּהּ (‘immāh, \"그와 함께 있던 남편에게도 주매\", 3:6 — 아담도 현장에서 방관하며 동참한 책임!), אַיֶּכָּה (’ayyekkāh, \"네가 어디 있느냐?\", 3:9 — 심판이 아닌 죄인을 찾으시는 아버지의 부르심), זֶרַע הָאִשָּׁה (여자의 후손, 3:15), כָּתְנוֹת עוֹר (kāṯənôṯ ‘ôr, 가죽옷 — 무화과나무 잎 치마를 대신하여 짐승의 피 흘림으로 지어 입히신 대속의 옷, 3:21).\n2. 사건 재구성 및 원시복음(창 3:15)의 구속사적 의의: 유혹과 범죄 (3:1-6): 뱀이 하나님의 말씀을 변개시켜(\"결코 죽지 아니하리라... 하나님과 같이 눈이 밝아질 줄을\") 하와를 미혹하매, 여자가 나무를 본즉 먹음직도 하고 보암직도 하고 지혜롭게 할 만큼 탐스럽기도 한 나무(요일 2:16 육신의 정욕·안목의 정욕·이생의 자랑 / 예수님의 광야 3대 시험[E024]과 정확히 대칭!)인지라 따 먹고 함께 있던 남편에게도 주매 먹음.\n• 무화과 잎 치마와 책임 전가 (3:7-13): 눈이 밝아져 벗은 줄을 알고 무화과나무 잎을 엮어 치마로 삼고 동산 나무 사이에 숨었으나, 찾아오신 하나님 앞에서 아담은 \"하나님이 주셔서 나와 함께 있게 하신 여자 그가\", 하와는 \"뱀이 나를 꾀므로\" 서로 책임을 전가함.\n• 창세기 3:15 원시복음(Protoevangelium)과 가죽옷 대속 (3:14-24): 인간에 대한 징벌 선언에 앞서 먼저 뱀(사탄)에게 \"내가 너로 여자와 원수가 되게 하고 네 후손도 여자의 후손과 원수가 되게 하리니 여자의 후손은 네 머리를 상하게 할 것이요 너는 그의 발꿈치를 상하게 할 것이니라\"(골고다 십자가에서 발꿈치가 상하시되 사탄의 머리를 박살 내신 예수 그리스도의 최초 복음 약속!) 선포하시고, 아담이 아내의 이름을 '하와'(생명)라 부른 믿음에 응답하여 친히 가죽옷을 지어 입히신 후 죄인인 상태로 생명나무를 먹고 영원히 죄 가운데 살지 않도록 에덴에서 내보내시고 그룹들과 두루 도는 불칼로 생명나무의 길을 지키게 하심(계 22:2, 14에서 그리스도의 피로 두루마리를 씻은 성도들에게 생명나무의 길이 다시 열림!).\n3. 대표 장면 시각 고증 (E003-S1~S2): S1. 선악과를 사이에 둔 하와와 함께 서 있는 아담, 그리고 창 3:15 원시복음이 선포되는 준엄한 빛. .\n• S2. 시든 무화과 잎 대신 하나님이 지어 입히신 양가죽 튜닉(코트노트 오르)을 입고 에덴 동편 경작지로 나아가는 아담과 하와.",
