      "dossierMd": "■ [E004] 노아의 방주 건조와 대홍수 심판 및 무지개 언약 (Noah's Ark & Rainbow Covenant)\n1. 기본 메타데이터: 성경 본문: 창세기 6:1~9:17 / 사 54:9; 마 24:37-39; 히 11:7; 벧전 3:20-21; 벧후 2:5 / 연결 인물: P003 노아, P205 므두셀라, P206 셈, P301 함, P302 야벳.\n• 핵심 원어 및 수치 고증: 방주(테바, תֵּבָה): 돛이나 노나 키(조타 장치)가 있는 '배'(’ŏniyyāh)가 아니라, 오직 하나님의 섭리에 맡겨 물 위에 뜨도록 설계된 직육면체 상자형 구조물(모세의 갈대 상자 출 2:3과 동일 단어!).\n• 크기: 길이 300규빗(약 135m) × 너비 50규빗(약 22.5m) × 높이 30규빗(약 13.5m), 고페르 나무(삼나무/잣나무류) 3층 구조, 안팎에 역청(kōp̄er — '속죄하다'[kāpar]와 동일 어근으로 진노의 물을 막아 주는 대속의 코팅!)을 칠함.\n• 대홍수 연대기 (총 370일): 노아 600세 되던 해 2월 17일 큰 깊음의 샘들이 터지고 하늘의 창문들이 열려 40주야 폭우 → 150일간 물이 땅에 넘침 → 7월 17일 아라랏산에 방주가 머묾 → 까마귀와 비둘기 파송(두 번째에 새 감람 잎사귀를 물고 옴, 8:11) → 601세 2월 27일 온 땅이 말라 8식구(노아 부부와 세 아들 부부)가 방주에서 나와 정결한 짐승과 새로 첫 번제를 드리고 구름 속 무지개(케셰트, 전쟁의 활을 하늘 방향으로 걸어 두신 평화 언약!) 언약을 받음.\n2. 대표 장면 시각 고증 (E004-S1~S2): S1. 육지 한가운데 세워진 거대한 직육면체 상자형 목조 방주(테바, 뱃머리·돛대 없는 상자형!)로 쌍쌍이 들어가는 동물들과 8인 가족, 그리고 여호와께서 친히 닫으시는 방주 문(창 7:16).\n• S2. 아라랏산 바위 위 자연석 번제단에서 피어오르는 향기로운 번제 연기와 하늘을 가로지르는 찬란한 무지개 언약 (창 8:20~9:17).",
