      "isPillar": true,
      "comparisonKey": null,
      "dossierMd": "■ [E005] 바벨탑 사건과 온 땅의 언어 혼잡·민족 분산 (Tower of Babel)\n1. 기본 메타데이터: 성경 본문: 창세기 11:1-9 / 습 3:9(순결한 입술 회복 예언); 행 2:4-11(오순절 성령 강림으로 각 나라 방언이 복음 안에서 하나 됨) / 연결 인물: P303 니므롯, P206 셈.\n• 핵심 원어 및 고고학 고증: 건축 재료 대조 (창 11:3): 팔레스타인 산지와 달리 돌이 없는 메소포타미아 남부 시날 평지의 지형적 특징 그대로, \"벽돌을 만들어 견고히 굽자 하고 이에 벽돌로 돌을 대신하며 역청(아스팔트 타르)으로 진흙을 대신하고\" 쌓아 올린 고대 메소포타미아 계단식 신전 탑(지구라트, Ziggurat — 바벨론 '에테메난키'[하늘과 땅의 기초 집]).\n• 인간의 두 가지 불순종 동기 (11:4): ① \"그 꼭대기를 하늘에 닿게 하여 우리 이름을 내고\" (하나님의 이름 대신 인간의 명예를 높임), ② \"온 지면에 흩어짐을 면하자\" (창 9:1 \"땅에 충만하라\"는 명령을 정면 거부).\n• 어원 유희: 당시 사람들은 '바벨'(Bāḇili)을 '신들의 문'이라 불렀으나, 성경은 히브리어 '발랄'(בָּלַל, 혼잡하게 하다)로 풀어 \"여호와께서 거기서 온 땅의 언어를 혼잡하게 하셨음이니라\"(11:9) 풍자함. 그리고 바벨탑 심판 바로 다음 절(창 11:10~12:3)에서 하나님은 '자기 이름을 내기 위해 모인 바벨 사람들' 대신, 한 사람 아브람을 불러 \"내가 네 이름을 창대하게 하리니 너는 복이 될지라\"(창 12:2) 구속사적 대안을 시작하심!\n2. 대표 장면 시각 고증 (E005-S1): S1. 시날 평지 위 구운 벽돌과 검은 역청으로 쌓아 올리던 거대한 사각 계단형 지구라트(Ziggurat) 건설 현장에서, 갑자기 서로 말을 알아듣지 못해 도구를 내려놓고 사방으로 흩어지는 군중들 (창 11:3-9): .",
