      "dossierMd": "■ [E006] 아브라함의 부르심과 쪼갠 고기 사이의 횃불 언약 (Call of Abraham & Covenant of the Torch)\n1. 기본 메타데이터: 성경 본문: 창세기 12:1-9; 15:1-21 / 행 7:2-5; 롬 4:1-25; 갈 3:6-18; 히 11:8-10 / 연결 인물: P004 아브라함, P005 사라, P208 롯, P212 다메섹 엘리에셀.\n• 핵심 원어: לֶךְ־לְךָ (leḵ-ləḵā, \"너는 너를 위하여 떠나가라\", 12:1), וְהֶאֱמִן בַּיהוָה וַיַּחְשְׁבֶהָ לּוֹ צְדָקָה (\"아브람이 여호와를 믿으니 여호와께서 이를 그의 의로 여기시고\", 창 15:6 — 성경 전체 이신칭의 교리의 대초석!), כָּרַת בְּרִית (kāraṯ bərîṯ, 언약을 '자르다/체결하다', 15:18).\n2. 사건 전개 및 횃불 언약의 구속사적 의미: 갈대아 우르와 하란을 떠나 갈 바를 알지 못하고 말씀만 따라 가나안에 들어와 세겜과 벧엘에 제단을 쌓음(창 12장) → 15장에서 무자(無子)한 아브람을 밤하늘 밖으로 데리고 나가 뭇별을 셀 수 있나 보라, 네 자손이 이와 같으리라 하시매 아브람이 여호와를 믿어 의롭다 하심을 얻음 → 땅 기업에 대한 확증으로 삼 년 된 암소·암염소·숫양을 둘로 쪼개어 마주 벌여 놓았을 때, 해가 져서 어두울 때에 아브람은 깊이 잠들고 오직 하나님을 상징하는 '연기 나는 화로가 보이며 타는 횃불'만 홀로 그 쪼갠 고기 사이로 지나가심(창 15:17).\n• 신학적 핵심: 고대 근동의 종주권 조약에서는 양측이 함께 쪼갠 짐승 사이로 지나가며 \"언약을 어기면 이 짐승처럼 쪼개진다\"고 맹세했으나, 창 15장에서는 하나님 홀로 쪼갠 고기 사이로 지나가심으로써 인간의 불순종으로 인한 언약 파기의 저주까지 하나님 자신이(장차 골고다 십자가에서 찢기실 성자 그리스도의 몸으로!) 홀로 다 짊어지시겠다고 보증하신 무조건적 은혜 언약임.\n3. 대표 장면 시각 고증 (E006-S1~S2): S1. 쏟아지는 중동 밤하늘의 무수한 별들 아래에서 장막 밖에 나와 하늘을 우러러보는 아브람과 곁에 선 여호와의 임재 (창 15:5-6).\n• S2. 짙은 어둠 속에서 양쪽으로 벌여 놓은 쪼갠 제물들 사이로 연기 나는 화로와 타는 횃불이 홀로 지나가는 장엄한 언약 장면 (창 15:17).",
