      "dossierMd": "■ [E007] 모리아산 이삭 번제 시험(아케다)과 여호와 이레의 숫양 대속 (Binding of Isaac on Mount Moriah)\n1. 기본 메타데이터: 성경 본문: 창세기 22:1-19 / 대하 3:1(모리아산 = 솔로몬 성전산); 요 8:56; 롬 8:32; 히 11:17-19(\"하나님이 능히 이삭을 죽은 자 가운데서 다시 살리실 줄로 생각한지라\"); 약 2:21-23 / 연결 인물: P004 아브라함, P006 이삭, P026 예수 그리스도.\n2. 사건 재구성 및 그리스도의 십자가 대속 예표 7단 대응: ① \"네 아들 네 사랑하는 독자 이삭\" (창 22:2 ↔ 요 3:16 독생자) → ② 사흘 길을 걸어 모리아산을 바라봄 (22:4 ↔ 사흘 동안 이미 마음속에서 아들을 바치고 부활로 돌려받은 시간, 히 11:19) → ③ 종들에게 \"내가 아이와 함께 저기 가서 예배하고 우리가 너희에게로 돌아오리라\" (22:5, 부활 신앙 고백!) → ④ 번제 나무(장작)를 아들 이삭에게 지우고(22:6 ↔ 십자가 나무를 지고 골고다에 오르신 예수님, 요 19:17) 아브라함은 불과 칼을 든 채 두 사람이 동행함 → ⑤ \"내 아버지여... 불과 나무는 있거니와 번제할 어린양은 어디 있나이까\" / \"내 아들아 번제할 어린양은 하나님이 자기를 위하여 친히 준비하시리라\"(22:7-8) → ⑥ 노년의 아브라함을 충분히 제압할 수 있는 건장한 청소년/청년 이삭이 자발적으로 결박당해 제단 나무 위에 누움(22:9) → ⑦ \"네가 네 아들 네 독자까지도 내게 아끼지 아니하였으니 내가 이제야 네가 하나님을 경외하는 줄을 아노라\" 하시며 뒤편 수풀에 두 뿔이 걸린 숫양(아일)을 예비하사 아들을 대신하여 번제로 드리게 하시고 그 땅 이름을 '여호와 이레'(여호와의 산에서 준비되리라)라 부름(22:12-14).\n3. 대표 장면 시각 고증 (E007-S1~S2): S1. 번제 장작을 등에 짊어진 건장한 청년 이삭과 횃불 화로·단검을 든 백발의 아브라함이 모리아산 돌길을 나란히 오르는 장면 (창 22:6-8): .\n• S2. 자연석 제단 위 결박된 이삭 위로 멈춘 아브라함의 손과 뒤편 가시덤불 수풀에 두 뿔이 걸려 있는 흠 없는 숫양 (창 22:10-13).",
