      "dossierMd": "■ [E008] 야곱의 벧엘 사닥다리 꿈과 얍복강 밤중 씨름('이스라엘' 개명) (Bethel & Jabbok)\n1. 기본 메타데이터: 성경 본문: 창세기 28:10-22; 32:22-32 / 호 12:3-4(\"울며 그에게 간구하였으며\"); 요 1:51(\"하늘이 열리고 하나님의 사자들이 인자 위에 오르락내리락하는 것을 보리라\") / 연결 인물: P007 야곱(이스라엘), P026 예수 그리스도.\n2. 두 사건의 구속사적 수미쌍관: 하란 도피길의 벧엘 사닥다리 (창 28:10-22): 형 에서를 피해 빈손으로 도망치던 야곱이 루스(벧엘) 들판에서 한 돌을 가져다 베개로 삼고 누워 잘 때, 땅 위에서 하늘에 닿은 사닥다리(계단형 경사로, sullām)에 하나님의 사자들이 오르내리고 그 위에서 여호와께서 \"내가 너와 함께 있어 네가 어디로 가든지 너를 지키며 너를 이끌어 이 땅으로 돌아오게 할지라\" 약속하심. 야곱이 아침에 일어나 베개 돌을 기둥으로 세우고 기름을 부어 '벧엘'(하나님의 집)이라 부름(요 1:51에서 예수님은 자신이 곧 하늘과 땅을 잇는 유일한 사닥다리[중보자]이심을 선언하심!).\n• 20년 만의 귀향길 얍복강 브니엘 씨름 (창 32:22-32): 밤에 두 아내와 열한 아들을 얍복강 나루로 먼저 건네보내고 홀로 남았을 때, 어떤 사람(여호와의 사자)이 날이 새도록 야곱과 씨름하다가 야곱의 허벅지 관절(환도뼈)을 치매 어긋남. 자기 힘의 근원이던 환도뼈가 꺾인 순간 야곱은 힘으로 버티던 씨름을 멈추고 울며 매달려(호 12:4) \"당신이 내게 축복하지 아니하면 가게 하지 아니하겠나이다\" 간구하여, '발꿈치를 잡은 속이는 자(야곱)'에서 '하나님과 겨루어 이긴 자 / 하나님이 다스리시는 자(이스라엘, יִשְׂרָאֵל)'로 새 이름을 받고 브니엘('하나님의 얼굴')의 아침 해를 맞이함.\n• S2. 동터 오는 얍복강 물가에서 환도뼈가 어긋난 다리를 절면서도 날개 없는 '어떤 사람'의 옷자락을 붙잡고 눈물로 축복을 간구하는 야곱 (창 32:24-31).",
