      "isPillar": true,
      "comparisonKey": null,
      "dossierMd": "■ [E009] 요셉의 애굽 총리 등극과 형제 용서 및 야곱 가문 70인 입애굽 (Joseph Exalted & Forgiveness)\n1. 기본 메타데이터: 성경 본문: 창세기 41:1~46:34; 50:15-21 / 시 105:17-22; 행 7:9-15 / 연결 인물: P008 요셉, P007 야곱, P218 유다, P222 베냐민.\n2. 사건 전개 및 창세기 전체의 신학적 결론(창 50:20): 도단 구덩이와 보디발 집·감옥 13년의 연단을 거친 30세 요셉이 바로의 꿈을 해석하여 애굽 온 땅의 총리(사브낫바네아)가 됨 → 7년 풍년 비축 후 대기근 때 곡식을 사러 온 형들을 시험하여(시므온 결박·베냐민의 자루 속 은잔) 형들이 22년 전의 죄를 뉘우치고 유다가 베냐민 대신 종이 되겠다고 눈물로 탄원하는 참된 회개를 확인한 뒤, 모든 애굽 시종을 물리고 방성대곡하며 \"나는 요셉이라 내 아버지께서 아직 살아 계시니이까... 당신들이 나를 이곳에 팔았다고 해서 근심하지 마소서 한탄하지 마소서 하나님이 생명을 구원하시려고 나를 당신들보다 먼저 보내셨나이다\"(창 45:3-5) 용서함 → 야곱과 온 가문 70인이 고센 땅에 정착하여 큰 민족을 이루고, 야곱 사후 두려워하는 형들에게 \"당신들은 나를 해하려 하였으나 하나님은 그것을 선으로 바꾸사 오늘과 같이 많은 백성의 생명을 구원하게 하시려 하셨나니\"(창 50:20) 창세기 전체의 섭리 신학을 선포함.\n3. 대표 장면 시각 고증 (E009-S1~S2): S1. 수염을 말끔히 깎고 인장 반지·흰 세마포 옷·금사슬 목걸이를 착용한 30세 총리 요셉이 버금 수레를 타고 애굽 곡물 창고를 지휘하는 장면 (창 41:41-43).\n• S2. 시종들을 다 물린 총리 관저 홀에서 베냐민의 목을 안고 울며 형제들과 입 맞추어 화해하는 요셉 (창 45:1-15).",
