      "dossierMd": "■ [E010] 호렙산 떨기나무 불꽃 현현과 모세의 소명('나는 스스로 있는 자니라') (Burning Bush & Call of Moses)\n1. 기본 메타데이터: 성경 본문: 출애굽기 3:1~4:17 / 신 33:16(\"가시떨기나무 가운데에 계시던 이의 은혜\"); 막 12:26; 행 7:30-35 / 연결 인물: P009 모세, P010 아론, P227 이드로.\n• 핵심 원어: סְנֶה (səneh, 광야 가시떨기나무 — 시내산[Sînay] 지명과 어근 연결), אֶהְיֶה אֲשֶׁר אֶהְיֶה (’Ehyeh ’ăšer ’Ehyeh, \"나는 스스로 있는 자니라\" → 언약의 이름 여호와[יְהוָה, YHWH] 계시, 출 3:14-15).\n2. 사건 재구성 및 신학적 의미: 미디안 광야에서 장인 이드로의 양 떼를 치던 80세 모세가 하나님의 산 호렙에 이르렀을 때, 가시떨기나무에 불이 붙었으나 나무가 사라지지 아니하는(애굽의 고난 풀무 속에서도 소멸되지 않는 이스라엘과 그 가운데 함께하시는 하나님의 임재 상징!) 기이한 광경을 봄 → \"모세야 모세야! ... 이리로 가까이 오지 말라 네가 선 곳은 거룩한 땅이니 네 발에서 신을 벗으라\" → \"내가 애굽에 있는 내 백성의 고통을 분명히 보고 그들이 그들의 감독자로 말미암아 부르짖음을 듣고 그 근심을 알고 내가 내려가서...\"(출 3:7-8) → 다섯 번이나 주저하며 사양하는 모세에게 지팡이·품속의 손 표적과 함께 \"내가 반드시 너와 함께 있으리라\" 약속하시고 형 아론을 대변자로 붙여 출애굽 구원자로 파송하심.\n3. 대표 장면 시각 고증 (E010-S1): S1. 호렙산 바위 기슭에서 타오르되 재가 되지 않는 가시떨기나무 불꽃 앞에서, 샌들을 벗어 옆에 두고 맨발로 무릎을 꿇은 채 지팡이를 짚고 얼굴을 가린 80세 백발 목자 모세 (출 3:2-6).",
