      "dossierMd": "■ [E011] 애굽 10대 재앙과 어린양의 피 유월절 제정 및 출애굽 대행진 (Ten Plagues & The First Passover)\n1. 기본 메타데이터: 성경 본문: 출애굽기 7:1~13:22 / 민 33:3-4(\"애굽의 모든 신에게 벌을 주셨더라\"); 요 1:29; 19:36(유월절 양의 뼈를 꺾지 말라 성취); 고전 5:7(\"우리의 유월절 양 곧 그리스도께서 희생되셨느니라\"); 히 11:28 / 연결 인물: P009 모세, P010 아론, P026 예수 그리스도.\n2. 애굽의 우상들을 직접 심판하신 10대 재앙과 유월절 대속 구도: 10대 재앙의 신학적 과녁 (출 12:12 \"내가 애굽의 모든 신을 심판하리라\"): ① 나일강 피(하피·크눔 나일강 신), ② 개구리(헤케트 다산 여신), ③ 이(게브 땅의 신), ④ 파리(케프리/고센 땅 구별 시작!), ⑤ 가축 돌림병(하토르·아피스 황소 신), ⑥ 악성 종기(임호테프·세크메트 의술 신), ⑦ 우박과 불(누트 하늘 여신), ⑧ 메뚜기(세트·오시리스 곡물 신), ⑨ 3일 흑암(태양신 아문-라의 완전한 굴복!), ⑩ 장자의 죽음(살아 있는 호루스라 자처한 파라오의 후계자 심판).\n• 제10재앙의 밤과 유월절(Pesaḥ, פֶּסַח, '넘어가다/방패로 감싸 보호하다') 제정 (출 12장): 아빕월(니산월) 10일에 흠 없고 일 년 된 수컷 어린양을 택해 두었다가 14일 해 질 때에 잡아 그 피를 우슬초 묶음에 적셔 집 좌우 문설주와 인방에 바르고, 그 밤에 허리에 띠를 띠고 발에 신을 신고 손에 지팡이를 잡고 불에 구운 고기를 무교병과 쓴 나물과 함께 급히 먹음. \"내가 피를 볼 때에 너희를 넘어가리니 재앙이 너희에게 내려 멸하지 아니하리라\"(출 12:13) — 유월절 어린양의 피가 곧 골고다 십자가에서 흘리신 예수 그리스도의 보혈의 완벽한 구약 원형임!\n3. 대표 장면 시각 고증 (E011-S1~S2): S1. 유월절 밤 고센 땅 히브리 가옥 문 앞에서 우슬초 다발에 적신 어린양의 붉은 피를 좌우 문설주와 위 인방에 바르는 가장과 안쪽에서 지팡이를 짚고 서서 무교병을 먹는 가족들 (출 12:7-11).\n• S2. 430년이 끝나는 밤, 요셉의 유골 관을 메고 가축 떼와 반죽 그릇을 옷에 싸서 어깨에 멘 채 횃불을 들고 라암셋에서 숙곳으로 행진해 나오는 이스라엘 60만 대군 (출 12:31-42).",
