      "isPillar": true,
      "comparisonKey": null,
      "dossierMd": "■ [E012] 홍해 도하 기적과 미리암·모세의 구원 찬양 (Crossing the Red Sea & Song of the Sea)\n1. 기본 메타데이터: 성경 본문: 출애굽기 14:1~15:21 / 시 106:7-12; 사 43:16; 고전 10:1-2(구름과 바다에서 모세에게 속하여 다 세례를 받고); 히 11:29; 계 15:3(모세의 노래와 어린양의 노래) / 연결 인물: P009 모세, P011 미리암.\n2. 사건 전개 및 구속사적 의미: 앞에는 홍해(Yam-Sûp̄)가 가로막히고 뒤에는 바로의 선발된 병거 육백 대가 추격해 와 백성들이 두려워 부르짖을 때, 모세가 \"너희는 두려워하지 말고 가만히 서서 여호와께서 오늘 너희를 위하여 행하시는 구원을 보라... 여호와께서 너희를 위하여 싸우시리니 너희는 가만히 있을지니라\"(출 14:13-14) 외침 → 하나님의 사자와 구름기둥이 뒤로 옮겨 애굽 진영에는 흑암을, 이스라엘 진영에는 밤을 비추는 빛이 됨 → 모세가 바다 위로 손을 내밀매 여호와께서 밤새도록 강한 동풍으로 바닷물을 물러가게 하시니 물이 갈라져 좌우에 벽이 되고 바다가 마른 땅이 되어 이스라엘이 건너가고, 뒤따라 들어온 바로의 병거와 마병은 새벽에 다시 합쳐진 물에 수장됨 → 건너편 해변에서 모세와 자손들이 '바다의 노래'(출 15:1-18: \"여호와는 나의 힘이요 노래시며 나의 구원이시로다... 여호와여 신 중에 주와 같은 자가 누구니이까\")를 부르고, 여선지자 미리암이 손에 소고(tōp̄, 금속 징 없는 원형 나무 프레임 드럼)를 잡고 모든 여인과 함께 춤추며 화답함(15:20-21).\n3. 대표 장면 시각 고증 (E012-S1~S2): S1. 불기둥과 구름기둥이 뒤편을 막아선 새벽, 모세가 지팡이를 든 손을 내밀자 좌우로 거대한 물벽이 서고 드러난 마른 바다 밑바닥 길을 따라 건너가는 이스라엘 백성들 (출 14:21-22).\n• S2. 아침 해가 떠오르는 홍해 건너편 해변에서 금속 징 없는 고대 원형 가죽 소고(토프)를 치며 여인들과 함께 구원의 하나님을 찬양하는 미리암과 모세 (출 15:1-21).",
