      "dossierMd": "■ [E013] 시내산 강림과 십계명 두 돌판 수여 및 언약의 피 뿌림 (Sinai Covenant & Ten Commandments)\n1. 기본 메타데이터: 성경 본문: 출애굽기 19:1~24:18; 31:18 / 신 4:10-13; 5:1-22; 히 9:18-20; 12:18-24 / 연결 인물: P009 모세, P010 아론, P012 여호수아.\n2. 사건 전개 및 국가 언약 체결: 출애굽 제3월 시내 광야에 이르러 \"세계가 다 내게 속하였나니 너희가 내 말을 잘 듣고 내 언약을 지키면 너희는 모든 민족 중에서 내 소유(보배, səḡullāh)가 되겠고 너희가 내게 대하여 제사장 나라가 되며 거룩한 백성이 되리라\"(출 19:5-6; 벧전 2:9) 사명 선언 → 성결 준비 후 셋째 날 아침 우레와 번개와 빽빽한 구름과 심히 큰 나팔 소리 가운데 여호와께서 불 가운데서 시내산에 강림하사 십계명(열 말씀, 아세레트 하데바림 — 1~4계명 하나님 사랑 / 5~10계명 이웃 사랑)을 선포하심 → 출 24장에서 산 아래 제단과 이스라엘 12지파 열두 기둥을 세우고 언약서를 낭독한 뒤 백성이 \"여호와의 모든 말씀을 우리가 준행하리이다\" 응답하자, 모세가 피를 가져다가 백성에게 뿌리며 \"보라 이는 여호와께서 이 모든 말씀에 대하여 너희와 세우신 언약의 피니라\"(출 24:8 ↔ 예수님의 최후의 만찬 \"이것은 죄 사함을 얻게 하려고 많은 사람을 위하여 흘리는 바 나의 피 곧 언약의 피니라\", 마 26:28!) 선언함.\n3. 대표 장면 시각 고증 (E013-S1~S2): S1. 빽빽한 구름과 번개·불길이 타오르는 시내산 정상 아래 경계선에 서서 경외함으로 산을 우러러보는 이스라엘 회중 (출 19:16-19).\n• S2. 시내산 아래 12돌기둥 제단 앞에서 언약서 두루마리를 낭독한 후 양푼의 언약의 피를 우슬초로 백성들을 향해 뿌리는 모세 (출 24:4-8).",
