      "isPillar": true,
      "comparisonKey": null,
      "dossierMd": "■ [E014] 광야 성막(회막)과 언약궤 건립 및 여호와의 영광(쉐키나) 충만 (Tabernacle & Ark of the Covenant)\n1. 기본 메타데이터: 성경 본문: 출애굽기 25~31장(설계 식양); 35~40장(제작 및 완공 봉헌) / 요 1:14(\"말씀이 육신이 되어 우리 가운데 장막을 치시매\"); 히 8:5; 9:1-24 / 연결 인물: P009 모세, P010 아론, P230 브살렐과 오홀리압, P026 예수 그리스도.\n2. 성막의 공간 구조와 구속사적 그리스도 예표 도해: 하나님께서 시내산에서 보이신 하늘 성소의 모형(식양, taḇnîṯ)대로 브살렐과 오홀리압이 제작하여 제2년 첫째 달 초하루(출 40:17)에 세움:\n1. 성막 뜰 동쪽 문(청·자·홍색 실과 가늘게 꼰 베 휘장 20규빗): 유일한 출입구 → \"내가 곧 양의 문이라\"(요 10:9).\n2. 번제단(조각목에 놋을 입힌 네 뿔 제단): 희생제물의 피 흘림 → 골고다 십자가 대속.\n3. 물두멍(회막 문에서 수종드는 여인들의 놋거울로 만든 놋 대야): 제사장의 손발 씻음 → 말씀과 성령의 씻음(엡 5:26; 딛 3:5).\n4. 성소(떡상·순금 일곱 등잔대·금 분향단): 생명의 떡이신 그리스도(요 6:35), 세상의 빛이신 그리스도(요 8:12), 대제사장적 중보기도(히 7:25; 계 8:3).\n5. 휘장(그룹들을 수놓은 청·자·홍색 휘장): 그리스도의 육체(십자가 운명 순간 위로부터 아래까지 둘로 찢어져 지성소로 들어가는 새롭고 산 길을 엶, 마 27:51; 히 10:19-20).\n6. 지성소와 언약궤·속죄소(시은좌, kappōreṯ): 조각목에 순금을 입힌 궤(안에 십계명 두 돌판·만나 금항아리·아론의 싹 난 지팡이)와 두 그룹이 날개로 덮은 순금 속죄소 — 대속의 피가 뿌려질 때 심판의 보좌가 은혜의 보좌(시은좌, 롬 3:25 hilastērion; 히 4:16)가 됨!\n• 완공과 영광 임재 (출 40:33-38): 모세가 \"여호와께서 모세에게 명령하신 대로 되니라\"(출 39~40장에 18회 반복!) 다 마친 순간, 구름이 회막에 덮이고 여호와의 영광이 성막에 충만하여 낮에는 여호와의 구름이, 밤에는 불이 성막 위에 머묾.\n3. 대표 장면 시각 고증 (E014-S1~S2): S1. 브살렐과 오홀리압이 조각목에 순금을 입히고 두 그룹이 날개를 마주 편 언약궤와 속죄소, 일곱 가지 순금 등잔대(메노라)를 정교하게 완성하는 장면 (출 37:1-24).\n• S2. 제2년 정월 초하루 광야 진영 한가운데 완성된 성막 위로 거룩한 구름기둥과 불빛의 여호와의 영광(쉐키나)이 가득히 내려앉고 모세와 온 백성이 엎드려 경배하는 장면 (출 40:34-38).",
