      "comparisonKey": null,
      "dossierMd": "■ [E015] 요단강 도하와 여리고성 함락 및 세겜 언약 갱신 (Crossing the Jordan & Fall of Jericho)\n1. 기본 메타데이터: 성경 본문: 여호수아 3:1~6:27; 24:1-28 / 히 11:30-31 / 연결 인물: P012 여호수아, P237 기생 라합, P232 대제사장 엘리야살.\n2. 사건 전개 및 말씀 순종의 승리: 요단강 도하 (수 3~4장): 모맥 거두는 시기에 언덕에 넘치던 요단강 물에 언약궤를 멘 제사장들의 발이 잠기자마자 위에서부터 흐르던 물이 멀리 사르단에 가까운 아담 성읍 변방에 그쳐 일어서서 온 백성이 마른 땅으로 건너가고, 강바닥과 길갈에 열두 돌 기념비를 세워 후손들의 신앙 교육장으로 삼음.\n• 여리고성 함락 (수 6장): 굳게 닫힌 난공불락의 첫 성 여리고 앞에서 인간적인 공성 무기 대신 일곱 제사장이 일곱 양각나팔(쇼파르, šôp̄ārôṯ hayyôḇəlîm)을 잡고 언약궤 앞에서 행진하며 닷새 동안 하루 한 바퀴씩 침묵으로 돌고, 일곱째 날에는 일곱 바퀴를 돈 뒤 길게 나팔을 불 때 백성이 일제히 큰 소리로 외치매 성벽이 무너져 내려 점령함(단 창문에 붉은 줄을 매단 라합(P237)과 그의 온 집은 구원하여 이스라엘 중에 거하게 함).\n• 세겜 상수리나무 아래 언약 갱신 (수 24장): 정복과 분배를 마친 노년의 여호수아가 온 지파를 세겜에 모아 아브라함부터 지금까지 인도하신 구속사를 회고하며 \"만일 여호와를 섬기는 것이 너희에게 좋지 않게 보이거든... 오늘 택하라 오직 나와 내 집은 여호와를 섬기겠노라\"(수 24:15) 결단을 촉구하고 큰 돌을 증거비로 세움.\n3. 대표 장면 시각 고증 (E015-S1~S2): S1. 언약궤를 어깨에 멘 제사장들과 숫양 뿔로 만든 양각나팔(쇼파르 — 금속 트럼펫 절대 금지!) 일곱 개를 부는 제사장들 뒤에서 백성이 함성을 지르자 무너져 내리는 여리고의 진흙벽돌 성벽과 붉은 줄이 걸린 라합의 성벽 창문 (수 6:15-20).\n• S2. 세겜 성소 상수리나무 아래 큰 자연석 증거 돌 곁에서 율법책 두루마리를 펴 들고 \"오직 나와 내 집은 여호와를 섬기겠노라\" 선포하는 110세 노장 여호수아 (수 24:15, 26-27).",
