      "isPillar": true,
      "comparisonKey": null,
      "dossierMd": "■ [E016] 사무엘의 미스바 대각성 부흥회와 에벤에셀 승리 및 다윗 기름부음 (Mizpah Revival & Anointing of David)\n1. 기본 메타데이터: 성경 본문: 사무엘상 7:1-14; 16:1-13 / 시 78:70-72; 89:20; 행 13:22 / 연결 인물: P019 사무엘, P021 다윗, P020 사울.\n2. 사건 재구성 및 구속사 핵심: 미스바 회개와 에벤에셀 (삼상 7:1-14): 언약궤가 기럇여아림에 머문 지 20년이 지나 온 이스라엘이 여호와를 사모할 때, 사무엘이 \"너희가 전심으로 여호와께 돌아오려거든 이방 신들과 아스다롯을 너희 중에서 제거하고 너희 마음을 여호와께로 향하여 그만을 섬기라\" 선포하고 미스바에 모여 물을 길어 여호와 앞에 붓고 금식하며 \"우리가 여호와께 범죄하였나이다\" 회개함. 블레셋이 쳐들어오자 사무엘이 젖 먹는 어린양 하나를 가져다가 온전한 번제를 드리며 부르짖을 때 여호와께서 큰 우레를 발하여 블레셋을 어지럽게 하사 대승을 거두게 하시고, 미스바와 센 사이에 돌을 세워 '에벤에셀'(אֶבֶן הָעֵזֶר, \"여호와께서 여기까지 우리를 도우셨다\")이라 부름(아벡 전투에서 언약궤를 빼앗겼던 바로 그 지명 '에벤에셀'[삼상 4:1]의 수치를 참된 회개로 완전히 씻어낸 역전!).\n• 베들레헴 다윗 기름부음 (삼상 16:1-13): 사울이 버림받은 후 뿔에 기름을 채워 베들레헴 이새의 집에 간 사무엘이 장남 엘리압의 준수한 외모를 보고 마음에 감탄할 때, 여호와께서 \"사람은 외모를 보거니와 나 여호와는 중심(마음, lēḇāḇ)을 보느니라\"(16:7) 깨우치시고 들에서 양을 치던 막내 다윗에게 숫양 뿔 기름병(qeren haššemen)으로 기름을 부으시니 그날 이후로 여호와의 영이 다윗에게 크게 감동되니라.\n3. 대표 장면 시각 고증 (E016-S1~S2): S1. 미스바 언덕 번제단 연기와 쏟아지는 우레 구름 아래 다듬지 않은 자연석 기념비 '에벤에셀'을 세우는 사무엘 (삼상 7:9-12).\n• S2. 베들레헴 이새의 집 안에서 노선지자 사무엘이 숫양의 뿔 기름병(도자기·유리병 금지!)을 기울여 무릎 꿇은 소년 목동 다윗의 머리에 기름을 붓는 장면 (삼상 16:12-13).",
