      "isPillar": true,
      "comparisonKey": null,
      "dossierMd": "■ [E017] 엘라 골짜기 다윗과 골리앗의 대결('만군의 여호와의 이름') (David and Goliath)\n1. 기본 메타데이터: 성경 본문: 사무엘상 17:1-58 / 시 20:7; 히 11:32-34 / 연결 인물: P021 다윗, P249 골리앗, P020 사울.\n2. 사건 전개 및 신학적 대조: 블레셋 가드의 거인 장수 골리앗(키 6규빗 한 뼘, 놋 투구와 5천 세겔 비늘 갑옷, 놋 경갑과 베틀채 같은 창)이 40일 동안 조석으로 나와 이스라엘의 군대를 모욕할 때, 어깨 위만큼 더 큰 사울 왕과 온 군대는 눈에 보이는 무장과 체격에 압도되어 심히 두려워함.\n• 아버지의 심부름으로 진영에 왔다가 골리앗의 모욕을 들은 소년 다윗은 이 싸움을 '인간 대 인간'이 아니라 '살아 계시는 하나님의 군대를 모욕한 할례받지 않은 자 대 만군의 여호와'의 영적 구도로 파악함. 사울의 무거운 갑옷을 벗어 두고 시내에서 매끄러운 돌 다섯 개를 골라 목자의 주머니에 넣고 손에 가죽/양모 투석줄 물매(qela‘)를 든 채 나아가 \"너는 칼과 창과 단창으로 내게 나아오거니와 나는 만군의 여호와의 이름 곧 네가 모욕하는 이스라엘 군대의 하나님의 이름으로 네게 나아가노라... 또 여호와의 구원하심이 칼과 창에 있지 아니함을 이 무리에게 알게 하리라 전쟁은 여호와께 속한 것인즉 그가 너희를 우리 손에 넘기시리라!\"(삼상 17:45-47) 외치며 달려가 물맷돌 한 알로 골리앗의 이마를 맞춰 쓰러뜨림(장차 골고다에서 사탄의 머리를 깨뜨리실 다윗의 자손 예수 그리스도의 예표!).\n3. 대표 장면 시각 고증 (E017-S1): S1. 엘라 골짜기 시냇가에서 갑옷 없이 목동 튜닉과 가죽 주머니·막대기를 들고 오른손으로 고대 근동식 가죽 줄 물매(Y자 고무줄 새총 절대 금지!)를 힘차게 돌리며 거인 장수 골리앗을 향해 달려 나가는 소년 다윗 (삼상 17:40-49).",
