      "isPillar": true,
      "comparisonKey": null,
      "dossierMd": "■ [E018] 언약궤의 다윗성 안치와 영원한 다윗 언약(삼하 7장) 수여 (The Davidic Covenant)\n1. 기본 메타데이터: 성경 본문: 사무엘하 6:1~7:29; 역대상 15:1~17:27 / 시 89:3-4, 28-37; 132편; 사 9:6-7; 눅 1:32-33(가브리엘 수태고지 인용); 행 2:30 / 연결 인물: P021 다윗, P086 선지자 나단, P026 예수 그리스도.\n2. 사건 전개 및 구속사 4대 기둥 언약(아담·노아·아브라함·모세·다윗→새 언약)의 정점: 언약궤 다윗성 입성 (삼하 6장; 대상 15~16장): 1차 새 수레 운반 실패(베레스웃사)의 교훈을 거울삼아 율법 규례대로 레위인들이 어깨에 채를 메어 언약궤를 모시고, 다윗은 왕복 대신 흰 고운 베 겉옷과 베 에봇(’ēp̄ôḏ bāḏ)을 입고 여호와 앞에서 힘을 다해 춤추며 여섯 걸음마다 소와 살진 송아지로 제사를 드리고 다윗성 장막에 안치함.\n• 삼하 7장 다윗 언약과 '집(bayiṯ)'의 언어 유희 (삼하 7:1-29): 자신이 백향목 궁에 거할 때 하나님의 궤는 휘장 가운데 있음을 송구해하며 성전('집', bayiṯ)을 지어 드리려 한 다윗에게, 밤에 선지자 나단(P086)을 통해 여호와께서 \"네가 나를 위하여 내가 살 집(bayiṯ)을 건축하겠느냐... 여호와가 너를 위하여 집(bayiṯ, 영원한 왕조!)을 이루고... 네 몸에서 날 네 씨를 네 뒤에 세워 그의 나라를 견고하게 하리라 그는 내 이름을 위하여 집을 건축할 것이요 나는 그의 나라 왕위를 영원히 견고하게 하리라 나는 그에게 아버지가 되고 그는 내게 아들이 되리니... 네 집과 네 나라가 내 앞에서 영원히 보전되고 네 왕위가 영원히 견고하리라\"(삼하 7:11-16) 약속하심 — 1차적으로는 아들 솔로몬의 성전 건축으로, 궁극적으로는 다윗의 자손으로 오셔서 자기 육체의 성전을 세우시고 영원한 하나님 나라 보좌에 앉으신 예수 그리스도(마 1:1; 눅 1:32-33)에게서 완전 성취됨!\n3. 대표 장면 시각 고증 (E018-S1~S2): S1. 레위인들이 어깨에 채를 메어(수레 금지!) 언약궤를 운반하고 흰 베 에봇을 입은 다윗이 소형 수금(키노르)과 양각나팔 소리 속에 기쁨으로 춤추며 다윗성에 입성하는 장면 (삼하 6:14-15; 대상 15:15).\n• S2. 다윗성 장막의 언약궤 앞에 들어가 앉아(삼하 7:18) \"주 여호와여 나는 누구이오며 내 집은 무엇이기에 나를 여기까지 이르게 하셨나이까\" 감격의 감사 기도를 드리는 다윗 왕.",
