      "isPillar": true,
      "comparisonKey": null,
      "dossierMd": "■ [E019] 솔로몬의 예루살렘 제1성전 완공과 봉헌 기도 및 하늘 불 응답 (Dedication of Solomon's Temple)\n1. 기본 메타데이터: 성경 본문: 열왕기상 6:1~8:66; 역대하 3:1~7:22 / 대하 3:1(\"솔로몬이 예루살렘 모리아 산에 여호와의 전 건축하기를 시작하니 그곳은 전에 여호와께서 그의 아버지 다윗에게 나타나신 곳이라 여부스 사람 오르난의 타작마당에 다윗이 정한 곳이라\") / 연결 인물: P022 솔로몬, P259 대제사장 사독, P262 두로 왕 히람·기술자 히람.\n2. 사건 전개 및 성전 봉헌 기도의 신학: 출애굽 제480년(왕상 6:1, BC 966년) 둘째 달에 착공하여 돌 뜨는 곳에서 다듬어 가져오므로 성전 건축 현장에서 방망이나 도끼나 모든 철 연장 소리가 들리지 않게(왕상 6:7) 7년 반 동안 지어 완공함(주랑 앞 두 놋기둥 '야긴'과 '보아스', 12황소가 받친 '놋바다', 백향목과 순금 내소 지성소).\n• 언약궤 지성소 안치와 구름 영광 (왕상 8:1-11; 대하 5:2-14): 일곱째 달 절기(초막절)에 제사장들이 언약궤(그 안에는 모세가 호렙에서 넣은 두 돌판 외에 아무것도 없음, 왕상 8:9)를 지성소 그룹 날개 아래에 안치하고, 레위 찬양대가 세마포를 입고 제금·비파·수금과 나팔 부는 제사장 120명과 함께 일제히 소리를 내어 \"선하시도다 그의 자비하심이 영원히 있도다\" 찬양할 때 구름이 여호와의 전에 가득하여 제사장들이 능히 서서 섬기지 못함.\n• 솔로몬의 무릎 봉헌 기도와 하늘의 불 (왕상 8:22-54; 대하 6:12~7:3): 솔로몬이 성전 뜰 가운데 만든 놋 단 위에 서서 회중 앞에서 무릎을 꿇고 하늘을 향하여 손을 펴고 \"하늘과 하늘들의 하늘이라도 주를 용납하지 못하겠거든 하물며 내가 건축한 이 성전이오리이까\" 고백하며, 죄를 범한 백성이든 주의 이름을 듣고 먼 지방에서 온 이방인이든(왕상 8:41-43 — \"만민이 기도하는 집\"!) 이 성전을 향하여 기도하거든 하늘에서 들으시고 사하여 주옵소서 간구함. 기도를 마치자 하늘에서 불이 내려와 번제물과 제물들을 사르고 여호와의 영광이 그 전에 가득하매 온 백성이 박석 땅에 엎드려 경배함.\n3. 대표 장면 시각 고증 (E019-S1~S2): S1. 두 청동 기둥 '야긴'과 '보아스', 12황소 놋바다가 배치된 제1성전 앞뜰 놋 단 위에서 무릎을 꿇고 두 손을 하늘로 높이 편 채 봉헌 기도를 드리는 솔로몬 왕 (대하 6:13).\n• S2. 기도가 끝나는 순간 하늘에서 번제단 위로 맹렬한 여호와의 불이 내려오고 성전 전체에 영광의 구름이 가득 차자 박석 바닥에 일제히 엎드려 경배하는 이스라엘 온 회중 (대하 7:1-3).",
