      "comparisonKey": null,
      "dossierMd": "■ [E020] 갈멜산 엘리야와 바알·아세라 선지자 850인의 대결 및 불·큰비 응답 (Elijah on Mount Carmel)\n1. 기본 메타데이터: 성경 본문: 열왕기상 18:1-46 / 약 5:17-18(\"엘리야는 우리와 성정이 같은 사람이로되 그가 비가 오지 않기를 간절히 기도한즉 삼 년 육 개월 동안 땅에 비가 오지 아니하고 다시 기도하니 하늘이 비를 주고 땅이 열매를 맺었느니라\") / 연결 인물: P023 엘리야, P057 아합, P101 궁내대신 오바댜.\n2. 사건 재구성 (불로 응답하시는 참 하나님 vs 침묵하는 우상): 3년 반 가뭄 끝에 갈멜산으로 아합과 바알 선지자 450명·아세라 선지자 400명 및 온 이스라엘을 모은 엘리야가 \"너희가 어느 때까지 둘 사이에서 머뭇머뭇하려느냐 여호와가 만일 하나님이면 그를 따르고 바알이 만일 하나님이면 그를 따를지니라!\"(왕상 18:21) 도전하고 \"불로 응답하는 신 그가 하나님이니라\" 선언함.\n• 바알 선지자들이 아침부터 정오, 저녁 소제 드릴 때까지 제단 주위를 뛰놀며 칼과 창으로 피가 흐르기까지 자해하며 불렀으나 아무 소리도 없고 응답하는 자나 돌아보는 자가 아무도 없음(18:26-29).\n• 저녁 소제 드릴 때에 엘리야가 무너진 여호와의 제단을 야곱의 아들들의 지파 수효대로 열두 돌을 취하여 수축하고(분열된 남북 12지파가 언약 안에서 하나임을 선포!), 제단 주위에 도랑을 파고 통 넷에 물을 채워 번제물과 나무 위에 세 번(총 12통) 부어 도랑에까지 물이 가득 차게 한 뒤, 길게 외치지 않고 단 두 절의 기도(\"아브라함과 이삭과 이스라엘의 하나님 여호와여 주께서 이스라엘 중에서 하나님이신 것과 내가 주의 종인 것과 내가 주의 말씀대로 이 모든 일을 행하는 것을 오늘 알게 하옵소서 여호와여 내게 응답하옵소서 내게 응답하옵소서 이 백성에게 주 여호와는 하나님이신 것과 주는 그들의 마음을 되돌이키심을 알게 하옵소서\", 18:36-37)를 드리자 여호와의 불이 내려와 번제물과 나무와 돌과 흙을 태우고 도랑의 물까지 다 핥는지라 온 백성이 엎드려 \"여호와 그는 하나님이시로다! 여호와 그는 하나님이시로다!\" 외침 → 이어 갈멜산 꼭대기로 올라가 땅에 꿇어 엎드려 얼굴을 무릎 사이에 넣고 일곱 번 사환을 보내기까지 간절히 기도하여 손바닥만 한 작은 구름에서 시작된 큰비로 가뭄을 끝내고 여호와의 능력으로 아합의 마차보다 앞서 이스르엘까지 달려감.\n3. 대표 장면 시각 고증 (E020-S1~S2): S1. 갈멜산 정상 위 열두 자연석으로 수축하고 도랑에 물이 흥건히 고인 제단 위로 하늘에서 강렬한 여호와의 불기둥이 내리꽂히고, 털겉옷과 가죽띠를 두른 엘리야 뒤에서 온 백성이 땅에 엎드려 외치는 장면 (왕상 18:30-39 — 현장에 이세벨은 없었으므로 이세벨 배치 금지!).\n• S2. 갈멜산 꼭대기 바위에서 얼굴을 두 무릎 사이에 넣은 채 간절히 비를 구하는 엘리야와 지중해 수평선 위로 떠오르는 사람의 손만 한 작은 구름 (왕상 18:42-44).",
