      "isPillar": true,
      "comparisonKey": null,
      "dossierMd": "■ [E021] 예루살렘 성전 파괴(남유다 멸망, BC 586)와 바벨론 유수 및 새 언약 예언 (Exile & New Covenant)\n1. 기본 메타데이터: 성경 본문: 열왕기하 25:1-21; 역대하 36:15-21; 예레미야 31:31-34; 39; 52장; 에스겔 36:26-27; 37:1-14 / 히 8:8-12; 10:16-17 / 연결 인물: P050 시드기야, P072 예레미야, P073 에스겔, P267 느부갓네살 2세.\n2. 심판의 어둠 한가운데서 선포된 '새 언약(렘 31:31)'과 '새 영·새 마음(겔 36:26)'의 소망: 부지런히 선지자들을 보내신 하나님의 경고를 끝내 비웃고 거절함으로 인해, 주전 586년(시드기야 제11년) 바벨론 군대에 의해 예루살렘 성벽이 헐리고 솔로몬 성전이 불타며 백성이 바벨론으로 사로잡혀 감(땅이 누리지 못했던 안식년을 채우기 위한 70년 포로, 대하 36:21).\n• 그러나 바로 그 멸망과 포로의 한복판에서 하나님은 예레미야와 에스겔을 통해 구속사 최고의 복음 약속인 '새 언약'(bərîṯ ḥăḏāšāh, בְּרִית חֲדָשָׁה — '신약성경'[New Testament]이라는 명칭 자체의 기원!)을 선포하심: 예레미야 31:31-34: \"보라 날이 이르리니 내가 이스라엘 집과 유다 집에 새 언약을 맺으리라... 내가 나의 법을 그들의 속에 두며 그들의 마음에 기록하여 나는 그들의 하나님이 되고 그들은 내 백성이 될 것이라... 내가 그들의 악행을 사하고 다시는 그 죄를 기억하지 아니하리라.\"\n• 에스겔 36:26-27: \"또 새 영을 너희 속에 두고 새 마음을 너희에게 주되 너희 육신에서 굳은 마음(돌 같은 마음)을 제거하고 부드러운 마음(살 같은 마음)을 줄 것이며 또 내 영을 너희 속에 두어 너희로 내 율례를 행하게 하리니.\"\n3. 대표 장면 시각 고증 (E021-S1~S2): S1. 불타는 예루살렘 성벽 앞에서 눈물로 『예레미야애가』(\"주의 성실하심이 크시도소이다\")를 부르는 예레미야와 시위대 뜰에서 아나돗 밭 매매증서 토기 항아리와 '새 언약'(렘 31:31) 두루마리를 바룩과 함께 남기는 장면.\n• S2. 바벨론 그발 강가와 마른 뼈 골짜기에서 사방으로부터 생기가 불어와 심히 마른 뼈들이 살이 오르고 호흡이 들어가 큰 군대로 일어서는 에스겔 37장 부활 환상.",
