      "isPillar": true,
      "comparisonKey": null,
      "dossierMd": "■ [E022] 고레스 해방 조서와 제2성전 완공·수문 앞 광장 율법 부흥·성벽 재건 (Return & Restoration)\n1. 기본 메타데이터: 성경 본문: 역대하 36:22-23; 에스라 1~10장; 느헤미야 1~13장; 학개 1~2장; 스가랴 1~8장 / 사 44:28~45:1 / 연결 인물: P269 고레스 2세, P113 스룹바벨, P114 대제사장 여호수아, P083 학개, P084 스가랴, P115 에스라, P116 느헤미야.\n2. 포로귀환 3단계 회복의 입체적 구도: 제1차 귀환 (BC 538~516, '예배와 성전의 회복'): 예레미야의 70년 예언을 이루시려 여호와께서 바사 왕 고레스(P269, 고레스 원통 비문)의 마음을 감동시키사 성전 건축 조서를 내리게 하심 → 총독 스룹바벨(P113)과 대제사장 여호수아(P114)가 약 5만 명을 이끌고 돌아와 번제단과 성전 기초를 놓았고, 16년 중단 위기를 학개(P083)·스가랴(P084)의 예언(\"힘으로 되지 아니하며 능력으로 되지 아니하고 오직 나의 영으로 되느니라\", 슥 4:6)으로 돌파하여 주전 516년 제2성전을 완공함.\n• 제2차 귀환 (BC 458, '말씀과 거룩한 삶의 회복'): 학사 겸 제사장 에스라(P115)가 여호와의 율법을 연구·준행·교육하기로 결심하고(스 7:10) 아하와 강가에서 금식 기도한 후 귀환하여 공동체의 성결을 회복함.\n• 제3차 귀환 (BC 445, '공동체 성벽과 말씀 대부흥의 완성'): 총독 느헤미야(P116)가 기도와 \"한 손으로 일을 하며 한 손에는 병기를 잡고\"(느 4:17) 헌신으로 52일 만에 예루살렘 성벽을 완공한 뒤, 수문 앞 광장에서 학사 에스라가 나무 강단 위에서 율법책을 낭독·해석하자 온 백성이 \"아멘 아멘\" 울며 회개하고 초막절 기쁨과 언약 인봉으로 메시아 오실 길을 예비함(느 8~10장).\n3. 대표 장면 시각 고증 (E022-S1~S2): S1. 한 손에는 흙손과 돌을, 한 손에는 창을 들고 허리에 칼을 찬 채 느헤미야의 지휘 아래 예루살렘 성벽을 쌓아 올리는 유다 백성들 (느 4:17-18).\n• S2. 완공된 성벽 안 수문 앞 광장에서 높은 나무 강단 위에 선 학사 에스라가 대형 토라 양피지 두루마리를 펼치자, 아래 광장의 남녀 모든 회중이 일제히 자리에서 일어서서 두 손을 들고 \"아멘 아멘!\" 화답하며 눈물 흘리는 대부흥 장면 (느 8:5-6).",
