      "isPillar": true,
      "comparisonKey": null,
      "dossierMd": "■ [E023] 예수 그리스도의 성육신 수태고지와 베들레헴 탄생(목자·동방박사 경배) (Incarnation & Nativity)\n1. 기본 메타데이터: 성경 본문: 마태복음 1:18~2:12; 누가복음 1:26-38; 2:1-20; 요한복음 1:1-14 / 사 7:14; 9:6; 미 5:2; 갈 4:4(\"때가 차매 하나님이 그 아들을 보내사 여자에게서 나게 하시고\"); 빌 2:6-8 / 연결 인물: P026 예수 그리스도, P028 마리아, P135 남편 요셉, P334 베들레헴 목자들, P333 동방박사들.\n2. 사건 전개 및 성육신(Incarnation)의 구속사적 완결성: 나사렛 수태고지와 요셉의 순종 (눅 1:26-38; 마 1:18-25): 가브리엘 천사의 성령 잉태 예고에 처녀 마리아가 \"주의 여종이오니 말씀대로 내게 이루어지이다\" 순종하고, 의로운 사람 요셉이 주의 사자의 현몽(\"자기 백성을 그들의 죄에서 구원할 자이심이라\" 예수 / \"하나님이 우리와 함께 계시다\" 임마누엘)에 순종하여 마리아를 데려옴.\n• 베들레헴 호적령과 돌구유 탄생·목자들의 첫 경배 (눅 2:1-20): 로마 황제 가이사 아구스도의 천하 호적령조차 미가 5:2(베들레헴 에브라다) 예언을 이루시는 하나님의 섭리 도구로 쓰여, 다윗의 동네 베들레헴에서 첫아들을 낳아 강보로 싸서 구유(phatnē, 1세기 베들레헴 가옥 아래층 동굴의 석회암 돌구유)에 뉘었더니, 밤에 들에서 양을 지키던 목자들(P334)이 천군 천사의 \"지극히 높은 곳에서는 하나님께 영광이요 땅에서는 기뻐하심을 입은 사람들 중에 평화로다\" 찬송을 듣고 달려와 첫 증인이 됨.\n• 베들레헴 '집'(마 2:11)으로 찾아온 동방박사들의 경배: 이어 동방에서 별을 보고 찾아온 이방의 박사들(P333)이 베들레헴 집(oikia)에 들어가 어머니 마리아와 함께 있는 아기께 엎드려 경배하고 보배합을 열어 황금·유향·몰약을 드림으로써 유대인의 가장 낮은 목자들과 이방인의 가장 지혜로운 학자들이 모두 만왕의 왕께 경배함.\n3. 대표 장면 시각 고증 (E023-S1~S2): S1. 1세기 베들레헴 석회암 동굴 마구간의 바위 돌구유(북유럽식 목조 오두막 금지!) 안에 강보에 싸여 누인 아기 예수님과 마리아·요셉, 그리고 양털 외투와 지팡이를 들고 무릎 꿇어 경배하는 목자들 (눅 2:7, 16).\n• S2. 베들레헴의 소박한 석조 '집'(oikia, 마 2:11) 안에 들어가 어머니 마리아 품의 아기 예수님 앞에 엎드려 보배합(황금·유향·몰약)을 열어 바치는 동방박사들.",
