      "dossierMd": "■ [E024] 예수님의 요단강 수세(삼위일체 현현)와 광야 40일 금식·3대 시험 승리 (Baptism & Temptation)\n1. 기본 메타데이터: 성경 본문: 마태복음 3:13~4:11; 마가복음 1:9-13; 누가복음 3:21~4:13 / 사 42:1; 시 2:7; 신 8:3; 6:13, 16; 히 4:15(\"모든 일에 우리와 똑같이 시험을 받으신 이로되 죄는 없으시니라\") / 연결 인물: P026 예수 그리스도, P027 세례 요한.\n2. 사건 전개 및 '마지막 아담·참 이스라엘'로서의 승리: 요단강 물속 수세와 삼위일체 하나님의 동시 현현 (마 3:13-17): 세례 요한이 \"내가 당신에게서 세례를 받아야 할 터인데\" 말릴 때 \"이제 허락하라 우리가 이와 같이 하여 모든 의를 이루는 것이 합당하니라\" 하시며 죄 없으신 분이 죄인들의 자리에 내려가 요단강 물속에서 세례를 받으시고 물에서 올라오실새, 하늘이 열리고 하나님의 성령이 비둘기같이 내려 자기 위에 임하시고 하늘로부터 성부 하나님의 음성(\"이는 내 사랑하는 아들이요 내 기뻐하는 자라\")이 울려 퍼짐.\n• 광야 40일 금식과 신명기 말씀(\"기록되었으되\")으로 이기신 3대 시험 (마 4:1-11): 성령에게 이끌리어 마귀에게 시험을 받으러 광야로 가사 40일을 밤낮으로 금식하신 후, 첫 아담이 에덴에서 무너졌고 이스라엘이 광야 40년간 무너졌던 바로 그 세 가지 시험(① 돌들로 떡덩이가 되게 하라 → 신 8:3 \"사람이 떡으로만 살 것이 아니요 하나님의 입으로부터 나오는 모든 말씀으로 살 것이라\", ② 성전 꼭대기에서 뛰어내리라 → 신 6:16 \"주 너희의 하나님을 시험하지 말라\", ③ 천하 만국 영광을 줄 터이니 내게 엎드려 경배하라 → 신 6:13 \"사탄아 물러가라! 기록되었으되 주 너의 하나님께 경배하고 다만 그를 섬기라 하였느니라\")을 오직 기록된 말씀의 검으로 단번에 물리치심.\n3. 대표 장면 시각 고증 (E024-S1~S2): S1. 황토빛 하류 요단강 물속(허리 깊이 — 강가 마른 바위 위 조개껍데기 살수 금지!)에서 세례 요한에게 침례를 받고 물에서 올라오시는 예수님 위로 열리는 하늘 빛과 비둘기 형상의 성령 임재 (마 3:16-17).\n• S2. 메마른 유대 광야 유혹산 바위 위에서 사탄의 유혹을 향해 단호히 손을 들어 \"기록되었으되(Γέγραπται)!\" 말씀으로 물리치시는 예수님 (마 4:4-10).",
