      "isPillar": true,
      "comparisonKey": null,
      "dossierMd": "■ [E025] 갈릴리 산상수훈(팔복·주기도문·황금률) 선포와 열두 사도 세우심 (Sermon on the Mount)\n1. 기본 메타데이터: 성경 본문: 마태복음 5:1~7:29; 마가복음 3:13-19; 누가복음 6:12-49 / 연결 인물: P026 예수 그리스도, P029 베드로, P121~P131 12사도.\n2. 천국 대헌장(산상수훈, 마 5~7장)의 핵심 구조: 밤새 산에서 기도하신 후 열두 사도를 택하심 (눅 6:12-16; 막 3:14): \"이는 자기와 함께 있게 하시고 또 보내사 전도도 하며 귀신을 내쫓는 권능도 가지게 하려 하심이러라\" — 구약 12지파를 잇는 새 언약 하나님 나라 백성의 기초인 12사도를 세우심.\n• 산에 올라가 앉으사(1세기 유대 랍비의 공식 교육 자세!) 제자들과 무리에게 입을 열어 가르치심 (마 5:1-2):\n1. 팔복(Μακαρισμοί, 마 5:3-12): 심령이 가난한 자·애통하는 자·온유한 자·의에 주리고 목마른 자·긍휼히 여기는 자·마음이 청결한 자·화평케 하는 자·의를 위하여 박해를 받은 자의 복.\n2. 세상의 소금과 세상의 빛 & 율법의 완성 (5:13-48): \"내가 율법이나 선지자를 폐하러 온 줄로 생각하지 말라 폐하러 온 것이 아니요 완전하게 하려 함이라\" — 마음의 미움과 음욕까지 다스리는 내면의 의와 원수 사랑.\n3. 하나님 앞(은밀한 중에 보시는 아버지)에서의 구제·기도(주기도문, 마 6:9-13)·금식과 하늘 보물, 공중의 새와 들의 백합화 (\"너희는 먼저 그의 나라와 그의 의를 구하라 그리하면 이 모든 것을 너희에게 더하시리라\", 마 6:33).\n4. 비판 금지·\"구하라 찾으라 두드리라\"(7:7-11)·황금률(7:12)·좁은 문·열매로 아는 나무·말씀을 듣고 행하는 반석 위의 지혜로운 건축자(7:24-27)로 마감하시니 무리가 그의 가르치심에 놀람은 그 가르치시는 것이 권위 있는 자와 같고 그들의 서기관들과 같지 아니함일러라(7:28-29).\n3. 대표 장면 시각 고증 (E025-S1): S1. 푸른 갈릴리 호수가 내려다보이는 북서쪽 완만한 현무암 언덕(팔복산) 바위 위에 친근하고도 권위 있게 '앉으사'(마 5:1 — 서서 웅변하는 중세풍 배제!), 가까이 둘러앉은 12제자와 언덕을 메운 무리에게 들의 백합화와 공중의 새를 가리키며 천국 복음을 가르치시는 예수님.",
