      "dossierMd": "■ [E026] 벳새다 오병이어 급식 표적과 갈릴리 바다 위를 걸으심 및 생명의 떡 강론 (Feeding the 5000)\n1. 기본 메타데이터: 성경 본문: 마태복음 14:13-33; 마가복음 6:30-52; 누가복음 9:10-17; 요한복음 6:1-71 (부활 사건 이전에 4복음서 모두에 공통으로 수록된 유일한 기적 사건!) / 연결 인물: P026 예수 그리스도, P123 안드레, P124 사도 빌립, P029 베드로.\n2. 사건 전개 및 데가볼리 칠병이어(E142)와의 명확한 구별: 오병이어 급식 표적 (요 6:1-15): 목자 없는 양 같은 큰 무리를 불쌍히 여기사 떼를 지어 푸른 잔디 위에 오십 명씩, 백 명씩 앉히신 후, 안드레(P123)가 데려온 한 아이의 보리떡 다섯 개와 작은 물고기(opsaria) 두 마리를 가지사 하늘을 우러러 축사하시고 떼어 제자들에게 주시매 여자와 어린아이 외에 남자만 오천 명이 다 배불리 먹고 남은 조각을 거두니 열두 바구니(kophinos, 유대인들이 여행 시 메고 다니던 버들고리 바구니 12개 — 12제자 각자의 바구니에 가득 참!)가 차게 됨.\n• ★ 오병이어(마 14장; 요 6장) vs 칠병이어(마 15:32-39; 막 8:1-10) 비교 구분 (마 16:9-10 예수님 친히 구분!): 장소 및 대상: 갈릴리 북동쪽 벳새다 들녘 (유대인 무리, 유월절 무렵 푸른 잔디) (갈릴리 동남쪽 데가볼리 산지 (이방인 무리, 사흘간 함께 머묾))\n• 음식 및 인원: 보리떡 5개 + 물고기 2마리 → 성인 남자 5,000명 (떡 7개 + 작은 생선 두어 마리 → 성인 남자 4,000명)\n• 남은 그릇 원어: 열두 바구니 (코피노스 κόφινος, 12지파/12사도 상징 소형 바구니) (일곱 광주리 (스퓌리스 σπυρίς, 다메섹 성벽에서 바울이 타고 내려온 대형 광주리[행 9:25], 7은 이방 충만수))\n• 밤 사경(새벽 3~6시) 바다 위를 걸으심과 생명의 떡 강론 (마 14:22-33; 요 6:22-71): 무리가 억지로 임금 삼으려 하자 제자들을 재촉해 먼저 배를 태워 보내시고 홀로 산에 올라가 밤새 기도하신 뒤, 풍랑에 고난당하는 제자들에게 바다 위로 걸어오시며 \"안심하라 내니 두려워하지 말라\" 하시고 물에 빠져가는 베드로의 손을 즉시 내밀어 붙잡아 주심 → 이튿날 가버나움 회당에서 \"내가 곧 생명의 떡이니 내게 오는 자는 결코 주리지 아니할 터이요 나를 믿는 자는 영원히 목마르지 아니하리라\"(요 6:35) 및 베드로의 \"주여 영생의 말씀이 주께 있사오니 우리가 누구에게로 가오리이까\"(6:68) 고백으로 이어짐.\n3. 대표 장면 시각 고증 (E026-S1~S2): S1. 벳새다의 푸른 봄 잔디 언덕 위에 오십 명·백 명씩 떼 지어 앉은 수천 명의 무리 앞에서, 소년이 바친 보리떡 5개와 물고기 2마리를 두 손에 들고 하늘을 우러러 축사하시는 예수님과 열두 바구니를 든 제자들 (요 6:9-13).\n• S2. 거센 새벽 풍랑이 치는 갈릴리 호수 물 위를 걸어오시는 예수님께서 물속으로 빠져들며 \"주여 나를 구원하소서!\" 외치는 베드로의 손목을 힘있게 붙잡아 끌어 올리시는 장면 (마 14:29-31).",
