      "isPillar": true,
      "comparisonKey": null,
      "dossierMd": "■ [E027] 가이사랴 빌립보 신앙고백(\"주는 그리스도시요\")과 변화산 영광 현현 (Caesarea Philippi & Transfiguration)\n1. 기본 메타데이터: 성경 본문: 마태복음 16:13~17:13; 마가복음 8:27~9:13; 누가복음 9:18-36 / 벧후 1:16-18(베드로의 변화산 친목격 증언!) / 연결 인물: P026 예수 그리스도, P029 베드로, P121 야고보, P122 사도 요한, P009 모세, P023 엘리야.\n2. 공생애의 분수령 — 그리스도의 정체성(신앙고백)과 사명(십자가·부활 예고 및 변화산 영광): 가이사랴 빌립보의 질문과 신앙고백 (마 16:13-20): 황제 숭배 신전과 판(Pan) 우상 동굴이 있던 북단 가이사랴 빌립보 지방에서 \"너희는 나를 누구라 하느냐\" 물으실 때, 시몬 베드로가 \"주는 그리스도시요 살아 계신 하나님의 아들이시니이다\" 고백하매 주님께서 \"바요나 시몬아 네가 복이 있도다 이를 네게 알게 한 이는 혈육이 아니요 하늘에 계신 내 아버지시니라 또 내가 네게 이르노니 너는 베드로라 내가 이 반석 위에 내 교회를 세우리니 음부의 권세가 이기지 못하리라\"(복음서 최초로 '내 교회'[mou tēn ekklēsian] 선언!) 축복하심.\n• 제1차 수난·부활 예고와 자기 십자가의 도 (마 16:21-28): 비로소 자기가 예루살렘에 올라가 고난을 받고 죽임을 당하고 제삼일에 살아나야 할 것을 나타내시며, 항변하는 베드로를 꾸짖으시고 \"누구든지 나를 따라오려거든 자기를 부인하고 자기 십자가를 지고 나를 따를 것이니라\" 제자도를 선포하심.\n• 엿새 후 변화산 영광 현현 (마 17:1-13; 눅 9:28-36): 베드로·야고보·요한 세 제자를 데리고 높은 산에 올라가 기도하실 때에 그 얼굴이 해같이 빛나며 옷이 빛과 같이 희어졌고, 구약 율법의 대표인 모세(P009)와 선지자의 대표인 엘리야(P023)가 영광중에 나타나 장차 예수께서 예루살렘에서 이루실 '별세'(헬라어 exodos, έξοδος — 십자가와 부활을 통한 인류의 진정한 '출애굽'!)를 말함(눅 9:31). 빛난 구름 속에서 \"이는 내 사랑하는 아들이요 내 기뻐하는 자니 너희는 그의 말을 들으라!\"(신 18:15 모세 같은 선지자 예언 성취!) 음성이 들렸고 제자들이 눈을 들어 본즉 오직 예수 외에는 아무도 보이지 아니하더라(17:8).\n3. 대표 장면 시각 고증 (E027-S1~S2): S1. 가이사랴 빌립보의 거대한 암벽을 배경으로 제자들 앞에서 예수님을 향해 \"주는 그리스도시요 살아 계신 하나님의 아들이시니이다\" 고백하는 베드로 (마 16:16).\n• S2. 변화산 정상 위에서 얼굴이 해같이 빛나고 눈부신 흰 옷을 입으신 예수님 양옆에 모세와 엘리야가 서서 대화하고, 빛난 구름 아래에서 베드로·야고보·요한이 엎드려 경외하는 장면 (마 17:1-6).",
