      "scriptures": "마 26:17-56; 막 14:12-52; 눅 22:7-53; 요 13:1-18:11; 고전 11:23-26",
      "summary": "수건을 두르시고 제자들의 발을 씻기신 사랑의 새 계명, 떡과 잔으로 제정하신 새 언약 성찬, 그리고 \"나의 원대로 마시옵고 아버지의 원대로 하옵소서\" 겟세마네 순종",
