      "isPillar": true,
      "comparisonKey": null,
      "dossierMd": "■ [E028] 다락방 최후의 만찬(세족식·새 언약 성찬 제정)과 겟세마네 동산 피땀 기도 (Last Supper & Gethsemane)\n1. 기본 메타데이터: 성경 본문: 마태복음 26:17-46; 마가복음 14:12-42; 누가복음 22:7-46; 요한복음 13:1~17:26 / 고전 11:23-26; 히 5:7-9 / 연결 인물: P026 예수 그리스도, P029 베드로, P122 사도 요한, P131 가룟 유다.\n2. 수난주간 목요일 밤의 3대 구속사 사건: 세족식과 새 계명 (\"세상에 있는 자기 사람들을 사랑하시되 끝까지 사랑하시니라\", 요 13:1-35): 누가 크냐 다투던 제자들 앞에서 주님이 저녁 잡수시던 자리에서 일어나 겉옷을 벗고 수건을 가져다가 허리에 두르시고 대야에 물을 떠서 가장 낮은 종의 모습으로 제자들의 발을 씻기시며 \"내가 너희에게 행한 것같이 너희도 행하게 하려 하여 본을 보였노라... 새 계명을 너희에게 주노니 서로 사랑하라 내가 너희를 사랑한 것같이 너희도 서로 사랑하라\" 명하심.\n• 새 언약의 성찬(주의 만찬) 제정 (마 26:26-29; 눅 22:19-20; 고전 11:23-25): 떡(유월절 무교병)을 가지사 축복하시고 떼어 주시며 \"받아서 먹으라 이것은 너희를 위하여 주는 내 몸이니 나를 기념하여 이를 행하라\" 하시고, 또 잔을 가지사 감사 기도하시고 주시며 \"너희가 다 이것을 마시라 이것은 죄 사함을 얻게 하려고 많은 사람을 위하여 흘리는 바 나의 피 곧 새 언약(렘 31:31; 출 24:8 완결!)의 피니라\" 제정하심.\n• 겟세마네('기름 짜는 틀', Γεθσημανί) 동산의 피땀 기도 (마 26:36-46; 눅 22:39-46): 감람산 겟세마네 동산에서 세 제자보다 돌 던질 만큼 나아가 땅에 엎드려 땀이 땅에 떨어지는 핏방울같이 되기까지 힘쓰고 애써 더욱 간절히 기도하시며 \"내 아버지여 만일 할만하시거든 이 잔을 내게서 지나가게 하옵소서 그러나 나의 원대로 마시옵고 아버지의 원대로 하옵소서!\" 세 번 기도하심으로써, 에덴동산에서 자기의 원대로 선악과를 먹었던 첫 아담의 불순종을 겟세마네 동산에서 아버지의 원에 복종하신 마지막 아담의 순종으로 완전히 역전시키심(롬 5:19; 히 5:7-8).\n3. 대표 장면 시각 고증 (E028-S1~S2): S1. 예루살렘 다락방의 낮은 ㄷ자형 트리클리니움(Triclinium) 식탁과 올리브유 등잔불 아래(다빈치식 높은 식탁·의자 금지!), 허리에 세마포 수건을 두르고 청동 대야의 물로 베드로의 발을 씻기시는 예수님과 이어 무교병과 잔을 들어 성찬을 제정하시는 장면 (요 13:4-5; 눅 22:19-20).\n• S2. 유월절 보름달빛이 비치는 밤 겟세마네 동산의 고목 감람나무 뿌리와 바위 앞에 무릎을 꿇고 얼굴을 땅에 대어 핏방울 같은 땀을 흘리며 기도하시는 예수님 (눅 22:41-44).",
