      "dossierMd": "■ [E029] 골고다 십자가 대속 죽음(\"다 이루었다\")과 제3일 빈 무덤 부활·감람산 승천 (Crucifixion, Resurrection & Ascension)\n1. 기본 메타데이터: 성경 본문: 마태복음 27~28장; 마가복음 15~16장; 누가복음 23~24장; 요한복음 19~21장; 사도행전 1:1-11 / 사 53:1-12; 시 22:1-18; 고전 15:1-28; 빌 2:8-11; 히 9:12; 10:12-20 / 연결 인물: P026 예수 그리스도, P028 모친 마리아, P122 사도 요한, P140 막달라 마리아, P029 베드로, P127 도마, P199 빌라도, P277 회개한 강도, P278 로마 백부장, P144 니고데모, P145 아리마대 요셉.\n2. 인류 구속사의 절대 중심 — 십자가·부활·승천의 3단 완성: 골고다 십자가 대속과 가상칠언 (금요일 제3시[오전 9시]~제9시[오후 3시]):\n1. \"아버지여 저들을 사하여 주옵소서 자기들이 하는 것을 알지 못함이니이다\" (눅 23:34, 원수를 위한 대제사장 중보)\n2. \"내가 진실로 네게 이르노니 오늘 네가 나와 함께 낙원에 있으리라\" (눅 23:43, 회개한 강도 구원)\n3. \"여자여 보소서 아들이니이다... 보라 네 어머니라\" (요 19:26-27, 모친 마리아와 요한 부탁)\n4. \"엘리 엘리 라마 사박다니 (나의 하나님, 나의 하나님, 어찌하여 나를 버리셨나이까)\" (마 27:46; 시 22:1, 온 인류의 죄와 하나님의 진노를 홀로 다 짊어지신 대속의 절정, 고후 5:21; 갈 3:13)\n5. \"내가 목마르다\" (요 19:28; 시 69:21 성경 성취)\n6. \"다 이루었다! (Tetelestai, Τετέλεσται — '빚이 전액 다 지불되었다 / 구속 사역이 영원히 완수되었다'!)\" (요 19:30)\n7. \"아버지여 내 영혼을 아버지 손에 부탁하나이다\" (눅 23:46; 시 31:5)\n• 운명하시는 순간 성소 휘장이 위로부터 아래까지 둘로 찢어지고(하나님이 친히 위에서부터 찢으사 지성소 은혜의 보좌로 나아가는 길을 여심!) 백부장이 \"이 사람은 진실로 하나님의 아들이었도다\" 고백함.\n• 제3일 안식 후 첫날 새벽 빈 무덤 부활과 40일 현현 (마 28장; 요 20~21장; 고전 15:3-8): 사망이 그를 가두어 둘 수 없어 성경대로 사흘 만에 부활하사 막달라 마리아와 여인들, 베드로, 엠마오 두 제자, 다락방 열 제자와 도마, 디베랴 호수 일곱 제자, 갈릴리 산 500여 형제, 동생 야고보에게 확실한 많은 증거로 친히 살아 계심을 나타내심.\n• 지상명령(마 28:18-20; 행 1:8)과 감람산 구름 승천 (눅 24:50-53; 행 1:9-11): 손을 들어 제자들에게 축복하시더니 그들이 보는 데서 올려져 가시니 구름이 그를 가리어 보이지 않게 되고, 두 천사가 \"하늘로 가심을 본 그대로 오시리라\" 재림을 확증함.\n3. 대표 장면 시각 고증 (E029-S1~S3): S1. 제6시~제9시 어둠이 덮인 골고다 언덕 세 십자가와 simultaneously 예루살렘 성전 내부의 거대한 휘장이 위에서부터 아래로 둘로 갈라지는 구속사적 장면 (마 27:45-51).\n• S2. 부활의 첫 아침 동산 바위 굴무덤 입구에서 둥근 막음돌(Golal)이 굴려져 열리고 찬란한 새벽빛 가운데 살아나신 부활의 주님과 막달라 마리아의 만남 (요 20:1-18).\n• S3. 감람산 위에서 두 손을 들어 열한 사도를 축복하시며 빛난 구름을 타고 하늘로 올리어 가시는 승천 장면 (눅 24:50-51; 행 1:9-11).",
