      "isPillar": true,
      "comparisonKey": null,
      "dossierMd": "■ [E030] 마가 다락방 오순절 성령 강림(교회의 탄생)과 다메섹 사울의 회심 및 새 하늘과 새 땅 완성 (Pentecost, Damascus & New Jerusalem)\n1. 기본 메타데이터: 성경 본문: 사도행전 2:1-47; 9:1-22; 요한계시록 21:1~22:21 / 욜 2:28-32; 창 11:1-9(바벨탑 언어 혼잡의 역전); 창 1~2장(에덴 생명나무의 완성) / 연결 인물: P029 베드로, P030 바울, P155 다메섹 아나니아, P122 사도 요한, P026 예수 그리스도.\n2. 신약 교회 시대의 개막에서 영원한 하나님 나라 완성까지: 마가 다락방 오순절 성령 강림과 교회의 탄생 (행 2:1-47): 오순절 날이 이미 이르매 그들이 다 같이 한곳에 모였더니 홀연히 하늘로부터 급하고 강한 바람 같은 소리가 있어 온 집에 가득하며 불의 혀처럼 갈라지는 것들이 그들에게 보여 각 사람 위에 하나씩 임하더니 다 성령의 충만함을 받고 각 나라 언어로 하나님의 큰일을 말함(바벨탑[E005]에서 교만으로 흩어졌던 인류의 언어가 성령 안에서 복음으로 하나 되는 역전!). 베드로의 성령 충만한 첫 설교에 그날에 신도의 수가 삼천이나 더하매, 사도의 가르침을 받아 서로 교제하고 떡을 떼며 오로지 기도하기를 힘쓰는 초대교회가 탄생함.\n• 다메섹 도상 사울의 회심과 세계 선교 (행 9:1-22): 정오에 다메섹에 가까이 갔을 때 하늘로부터 해보다 더 밝은 빛이 둘러 비추며 \"사울아 사울아 네가 어찌하여 나를 박해하느냐... 나는 네가 박해하는 예수라\"(교회를 박해하는 것이 곧 부활하신 예수님의 몸을 박해하는 것임을 계시!) 음성을 듣고 이방인의 사도로 거듭나 안디옥·소아시아·유럽·로마 땅끝까지 복음이 확장됨.\n• 새 하늘과 새 땅·거룩한 성 새 예루살렘 강림 (계 21:1~22:21): 구속사 30대 기둥 사건의 최종 목적지 — 처음 하늘과 처음 땅이 없어지고 거룩한 성 새 예루살렘이 하나님께로부터 하늘에서 내려오니 \"보라 하나님의 장막이 사람들과 함께 있으매 하나님이 그들과 함께 계시리니... 모든 눈물을 그 눈에서 닦아 주시니 다시는 사망이 없고 애통하는 것이나 곡하는 것이나 아픈 것이 다시 있지 아니하리니 처음 것들이 다 지나갔음이러라\"(계 21:3-4). 하나님과 어린양의 보좌로부터 흘러나오는 수정 같이 맑은 생명수 강과 좌우에 있어 달마다 열두 가지 열매를 맺고 그 잎사귀들은 만국을 치료하는 생명나무가 회복되어 성도들이 세세토록 왕 노릇 하며 \"아멘 주 예수여 오시옵소서!\" 찬양으로 성경 66권이 완성됨.\n3. 대표 장면 시각 고증 (E030-S1~S3): S1. 예루살렘 마가의 다락방에서 합심 기도하던 120문도 각 사람 머리 위로 불의 혀처럼 갈라지는 성령의 임재가 내리고 성전 앞 광장에서 베드로가 수천 군중에게 설교하는 오순절 장면 (행 2:1-41).\n• S2. 다메섹 성문이 보이는 한낮의 광야 길에서 하늘로부터 쏟아지는 강렬한 빛 앞에 땅에 엎드러진 도보의 사울(말/낙마 묘사 절대 금지!)과 동행자들 (행 9:3-7).\n• S3. 수정 같이 맑은 생명수 강이 하나님과 어린양의 보좌로부터 흘러나오고 강 좌우에 달마다 열두 열매를 맺는 생명나무가 서 있는 거룩한 성 새 예루살렘의 영광 (계 21:1~22:5).",
