      "dossierMd": "• E034 하갈의 브엘라해로이('엘 로이') 현현과 할례 언약·아브라함과 사라 개명 (창 16:1~17:27) & E035 마므레 세 손님 대접과 아브라함의 중보기도 및 소돔·고모라 유황불 심판 (창 18:1~19:29): 하갈과 할례 언약 (E034): 술 길 샘물가에서 여종 하갈(P210)을 만나 주신 '엘 로이'(나를 살피시는 하나님)와, 13년 침묵 후 99세 아브람에게 나타나 \"나는 전능한 하나님(엘 샤다이)이라 너는 내 앞에서 행하여 완전하라\" 하시며 아브람→아브라함, 사래→사라로 개명하시고 언약의 표징으로 할례를 제정하심.\n• 마므레 환대와 소돔 중보·심판 (E035): 날이 뜨거울 때 마므레 상수리나무 장막 문에 앉아 있던 아브라함이 세 사람(여호와와 두 천사)을 발견하고 달려 나가 고운 가루 세 스아 떡과 기름진 송아지 요리로 극진히 대접하고 \"내년 이맘때 내가 정녕 네게로 돌아오리니 네 아내 사라에게 아들이 있으리라... 여호와께 능하지 못한 일이 있겠느냐\"(창 18:10, 14) 약속을 받음 → 소돔을 향하여 가실 때 아브라함이 여호와 앞에 그대로 서서 의인 50명에서 45명, 40명, 30명, 20명, 10명까지 여섯 번이나 낮추어 가며 \"세상을 심판하시는 이가 정의를 행하실 것이 아니니이까\" 중보기도함 → 새벽녘 두 천사가 소돔에서 롯(P208)과 아내·두 딸의 손을 잡아 끌어내어 소알 성으로 피신시키고 하늘로부터 유황과 불을 비같이 내려 소돔과 고모라를 엎으셨으나 롯의 아내는 뒤를 돌아보아 소금 기둥이 됨(창 19:26; 눅 17:32 \"롯의 처를 기억하라\").",
