      "dossierMd": "• E046 르비딤 제1차 반석 생수('반석을 치라')와 아말렉 전투 모세의 기도 손(여호와 닛시) 및 이드로의 사법 자문 (출 17:1~18:27): ★ [필수 사건 분리 기준] 광야 반석 생수 기적 2회 완벽 구별표: 시기 및 장소: 출애굽 직후 제1년, 르비딤(호렙산 반석, 맛사·므리바) (광야 유랑 마지막 해인 제40년 정월, 신 광야 가데스(므리바 물))\n• 하나님의 명령: \"나일강을 치던 네 지팡이를 손에 잡고 가라 내가 호렙산에 있는 그 반석 위 거기서 네 앞에 서리니 너는 그 반석을 치라(wəhikkîṯā ḇaṣṣûr)\" (출 17:5-6) (\"지팡이를 가지고 네 형 아론과 함께 회중을 모으고 그들의 목전에서 너희는 반석에게 명령하여 물을 내라 하라(wəḏibbartem ’el-hassela‘)\" (민 20:8))\n• 모세의 행동과 결과: 말씀대로 장로들의 목전에서 반석을 쳐서 생수를 냄 (순종!) (백성에게 분노하며 \"우리가 너희를 위하여 이 반석에서 물을 내랴\" 하고 그의 손으로 지팡이를 들어 반석을 두 번 침 → 물은 나왔으나 하나님의 거룩함을 나타내지 못한 죄로 모세·아론의 가나안 입성이 불허됨)\n• 구속사적 예표 (고전 10:4): 초림하신 그리스도께서 십자가에서 단번에 매 맞으사(치심을 받아) 생수의 강(성령)을 흘려보내심 (이미 단번에 매 맞으신 그리스도를 두 번 다시 십자가에 못 박을 수 없으며, 이제는 믿음의 말씀과 기도로('반석에게 말하여') 은혜를 구해야 함!)\n• 르비딤 아말렉 전투와 여호와 닛시 (출 17:8-16): 골짜기 아래에서는 젊은 장수 여호수아(P012)가 칼날로 싸우고, 산꼭대기에서는 모세(P009)가 하나님의 지팡이를 손에 들고 손을 들면 이스라엘이 이기고 손을 내리면 아말렉이 이기더니, 아론(P010)과 후르(P229)가 돌을 가져다 모세를 앉히고 해가 지도록 양쪽에서 손을 붙들어 올려 승리한 후 제단을 쌓고 '여호와 닛시'(여호와는 나의 깃발)라 부름.",
