      "dossierMd": "• E047 금송아지 배교 사건과 모세의 생명책 중보기도 및 깨어진 돌판 재수여·얼굴 광채 (출 32:1~34:35): 모세가 시내산에 올라간 40일 동안 백성이 아론을 압박하여 금 귀고리를 모아 부어 만든 송아지 우상을 세우고 뛰놀자, 진노하신 여호와께서 그들을 진멸하리라 하심 → 모세가 산에서 내려오다 두 증거판을 산 아래로 던져 깨뜨리고 레위 자손의 헌신으로 우상 숭배를 진압한 뒤, 이튿날 다시 산에 올라가 \"슬프도소이다 이 백성이 자기들을 위하여 금신을 만들었사오니 큰 죄를 범하였나이다 그러나 이제 그들의 죄를 사하시옵소서 그렇지 아니하시오면 원하건대 주께서 기록하신 책에서 내 이름을 지워 버려 주옵소서!\"(출 32:31-32, 장차 로마서 9:3 바울의 기도와 십자가 대속의 모형!) 생명을 건 중보기도를 드림 → 출 34장에서 처음과 같은 두 돌판을 다듬어 올라간 모세 앞에 여호와께서 구름 가운데 강림하사 \"여호와라 여호와라 자비롭고 은혜롭고 노하기를 더디하고 인자와 진실이 많은 하나님이라\"(출 34:6-7) 선포하시고 언약을 갱신하시니, 산에서 내려올 때 모세의 얼굴 피부에 광채(qāran)가 나므로 수건(masweh)으로 얼굴을 가림(뿔 조각 절대 금지!).",
