      "dossierMd": "• E048 제사장 위임식·나답과 아비후의 '다른 불' 심판 및 대속죄일 규례 (레 8~10; 16장) · E049 가데스바네아 12정탐꾼 보고와 고라 반역·아론의 싹 난 지팡이·제2차 반석 사건 (민 13~14; 16~17; 20장) · E050 불뱀과 광야의 놋뱀 구원·발람의 '한 별' 축복 예언 및 느보산 모세 임종 (민 21~24장; 신 34장): 핵심 시각·신학 포인트: ① 가데스바네아에서 에스골 골짜기 포도 한 송이 달린 가지를 둘이 막대기에 꿰어 메고 온 12정탐꾼 중 10명의 메뚜기 자화상 악평과 옷을 찢으며 \"그들은 우리의 먹이라 여호와께서 우리와 함께하시느니라\" 외친 여호수아·갈렙의 대조(E049), ② 고라 반역 후 12지파 지팡이 중 오직 레위 집을 대표한 아론의 지팡이에만 움이 돋고 순이 나고 살구꽃이 피고 살구 열매가 동시에 열린 부활 권능의 표징(E049), ③ 에돔 땅을 우회하며 원망하다 불뱀에 물려 죽어갈 때 모세가 놋뱀을 만들어 장대 위에 매달아 쳐다보는 자마다 모두 살아난 사건(요 3:14-15 \"모세가 광야에서 뱀을 든 것같이 인자도 들려야 하리니\" — 갈라진 두 마리 뱀 아스클레피오스 지팡이가 아니라 장대 위의 단일 청동 뱀으로 고증!)(E050), ④ 120세까지 눈이 흐리지 않고 기력이 쇠하지 않은 모세가 느보산(비스가 산꼭대기)에서 요단 건너편 약속의 땅 사방을 바라보고 여호와의 말씀대로 모압 땅에서 임종한 사건(E050).",
