      "dossierMd": "• E062 사울의 초대 왕 기름부음·야베스 길르앗 승리와 길갈 제사 월권·아말렉 불순종 (\"순종이 제사보다 낫고\", 삼상 9~13; 15장): 사무엘이 작은 토기 기름병(paḵ haššemen)을 취하여 사울의 머리에 붓고 초대 왕으로 세웠으나, 블레셋과의 믹마스 대치 중 백성이 흩어지자 사울이 제사장 직분을 침범하여 번제를 드렸고(삼상 13장), 아말렉 진멸 전쟁에서는 왕 아각과 가장 좋은 양과 소를 남긴 뒤 백성 핑계를 대다가 \"여호와께서 번제와 다른 제사를 그의 목소리를 청종하는 것을 좋아하심같이 좋아하시겠나이까 순종이 제사보다 낫고 듣는 것이 숫양의 기름보다 나으니 이는 거역하는 것은 점치는 죄와 같고 완고한 것은 사신 우상에게 절하는 죄와 같음이라 왕이 여호와의 말씀을 버렸으므로 여호와께서도 왕을 버려 왕이 되지 못하게 하셨나이다\"(삼상 15:22-23) 준엄한 폐위 선고를 받고 사무엘의 겉옷 자락이 찢어짐.",
