      "dossierMd": "• E067 다윗의 밧세바·우리아 범죄와 선지자 나단의 작은 암양 비유 책망(\"당신이 그 사람이라!\") 및 시편 51편 눈물의 회개 (삼하 11~12장; 시 51편) · E068 압살롬의 반역과 다윗의 눈물의 감람산 피난 (삼하 15~19장) · E069 아라우나(오르난) 타작마당 번제단 건립(모리아산 성전터 확정) (삼하 24장; 대상 21장) · E070 솔로몬의 기혼 샘 즉위·기브온 일천번제 지혜 간구 및 두 여인의 아기 재판 (왕상 1~3장; 대하 1장) · E071 스바 여왕 방문과 솔로몬 말년 타락·아히야의 열두 조각 옷 예언 (왕상 10~11장): 핵심 포인트: 나단(P086)의 \"당신이 그 사람이라!\" 책망 앞에 사울처럼 변명하지 않고 즉시 왕좌에서 내려와 \"내가 여호와께 죄를 범하였노라\" 엎드려 \"하나님이여 내 속에 정한 마음을 창조하시고 내 안에 정직한 영을 새롭게 하소서... 구원의 즐거움을 내게 회복시켜 주시고\"(시 51:10-12) 통회한 다윗(E067), 인구조사 징벌의 천사가 칼을 빼어 예루살렘을 향할 때 여부스 사람 아라우나(오르난)의 타작마당을 값을 다 주고 사서 번제단을 쌓아 염병을 그치게 하고 바로 그 자리가 아브라함의 모리아산이자 솔로몬 성전 부지(대하 3:1)로 확정된 구속사적 공간 연결(E069), 그리고 다윗의 노새를 타고 기혼 샘에서 즉위한 솔로몬(P022)이 기브온 회막의 브살렐 놋제단 위에서 일천번제를 드리고 백성을 재판할 '듣는 마음'(lēḇ šōmēa‘)을 구하여 응답받은 사건(E070).",
