      "dossierMd": "■ [E076] 나봇의 포도원 강탈 사건과 미가야 선지자의 두 보좌 환상 및 길르앗 라못 아합의 변장 전사 (왕상 21~22장; 대하 18장)\n• 핵심 참여 인물: P057 아합, P058 이세벨, P106 나봇, P023 엘리야, P091 미가야, P034 여호사밧.\n• 사건 재구성 및 신학·시각 고증:\n1. 나봇의 언약적 거절과 이세벨의 인장 모략 (왕상 21:1-16): 이스르엘 왕궁 곁 포도원을 채소밭으로 삼으려는 아합에게 나봇이 레위기 25:23 토지법에 따라 \"내 조상의 유산을 왕에게 주기를 여호와께서 금하실지로다\" 거절하자, 이세벨이 아합의 인장(ḥōṯām — 파피루스 점토 불라 봉인)으로 거짓 편지를 써 보내 금식을 선포하고 불량자 두 사람을 세워 나봇과 그의 아들들(왕하 9:26)을 돌로 쳐 죽이게 함.\n2. 사마리아 성문 어귀 타작마당의 지상 두 보좌 vs 하늘 여호와의 보좌 (왕상 22:10-28): 길르앗 라못 출전을 앞두고 아합과 여호사밧이 각기 왕복을 입고 보좌에 앉아 400명 거짓 선지자들의 아첨(그나아나의 아들 시드기야의 철뿔 퍼포먼스)을 들을 때, 이믈라의 아들 미가야(P091)가 홀로 \"여호와께서 내게 말씀하시는 것만 말하겠노라... 내가 보니 여호와께서 그의 보좌에 앉으셨고 하늘의 만군이 그의 좌우편에 모시고 서 있는데...\" 천상 어전 회의 환상과 아합의 전사를 선포하고 시드기야에게 뺨을 맞으면서도 굴하지 않음.\n3. 변장 출전과 '우연히' 날아온 화살 (왕상 22:30-38): 미가야의 예언을 피하려고 여호사밧에게는 왕복을 입히고 자신은 일반 군사로 변장하고 전장에 들어갔으나, 한 사람이 무심코(우연히, ləṯummô) 활을 당겨 아합 왕의 갑옷 솔기(청동 비늘갑옷 연결부 틈)를 맞히매 병거 가운데서 피를 흘리다 저녁에 죽고 사마리아 못에서 병거를 씻을 때 엘리야의 예언(왕상 21:19) 그대로 개들이 그의 피를 핥음 — 인간의 얄팍한 변장도 하나님의 공의로운 심판 화살을 결코 피할 수 없음을 보여 준 사건.",
