      "dossierMd": "■ [E077] 여호사밧의 율법 순회 교육과 모압·암몬 연합군 침공 앞 성전 합심 기도 및 브라가 골짜기 찬양대 대승 (대하 17; 20장)\n• 핵심 참여 인물: P034 여호사밧, P094 레위인 야하시엘.\n• 사건 재구성: 모압과 암몬 자손과 마온 사람들이 큰 무리로 엔게디에 침공해 오자 여호사밧이 두려워하여 여호와께로 낯을 향하여 간구하고 온 유다에 금식을 공포함 → 유다 모든 사람이 아내와 자녀와 어린이와 더불어 여호와의 전 새 뜰 앞에 서서 여호사밧이 \"우리에게밀려오는 이 큰 무리를 우리가 대적할 능력이 없고 어떻게 할 줄도 알지 못하옵고 오직 주만 바라보나이다!\"(대하 20:12) 기도할 때, 아삽 자손 레위인 야하시엘(P094)에게 여호와의 영이 임하여 \"이 큰 무리로 말미암아 두려워하거나 놀라지 말라 이 전쟁은 너희에게 속한 것이 아니요 하나님께 속한 것이니라... 너희는 가만히 서서 너희와 함께한 여호와가 구원하는 것을 보라\" 선포함 → 이튿날 아침 드고아 들로 나아갈 때 백성과 의논하여 노래하는 자들을 택하여 거룩한 예복을 입히고 군대 앞에서 행진하며 \"여호와께 감사하세 그의 인자하심이 영원하도다!\" 찬송을 시작할 때에 여호와께서 복병을 두어 적군들이 서로 쳐서 진멸하게 하시고 사흘 동안 전리품을 거둔 후 제4일에 브라가('송축/축복') 골짜기에서 여호와를 송축함.",
