      "summary": "겉옷으로 요단강을 갈라 건넌 후 불수레와 불말이 두 사람을 갈라놓고 엘리야가 회오리바람으로 승천한 사건과, 두 아들이 종으로 팔릴 위기에 처한 과부가 이웃에게 빈 그릇을 빌려 기름을 채워 빚을 갚은 구원 기적",
