      "title": "수넴 여인의 작은 방 대접과 죽은 아들의 소생 및 아람 군대장관 나아만의 요단강 일곱 번 목욕 치유(게하시의 탐욕과 나병)",
      "origTitle": "Shunammite's Son Raised & Naaman Healed in the Jordan",
      "releaseTier": "(구약역사90사건)",
      "tier": "",
      "axis": "3_분열왕국선지자포로축",
      "era": "북이스라엘 엘리사 사역기",
      "eraCategory": "북이스라엘 엘리사 사역기",
      "testament": "구약",
      "location": "수넴과 갈멜산 / 다메섹→사마리아→요단강",
      "scriptures": "왕하 4:8-37; 5:1-27; 눅 4:27",
      "summary": "수넴 여인의 믿음의 질주를 통한 아들 부활과, 포로로 잡혀간 이스라엘 어린 소녀의 한마디로 시작되어 교만을 내려놓고 요단강에 일곱 번 몸을 잠가 어린아이 살같이 깨끗해진 이방 장군 나아만의 회심",
      "status": "완료",
      "eventTags": [
        "3_분열왕국선지자포로축"
      ],
      "isPillar": false,
      "comparisonKey": null,
      "dossierMd": "■ [E078] 엘리야의 불수레·불말 회오리바람 승천(엘리사의 갑절 영감)과 과부의 빈 그릇 기름병 이적 (왕하 2; 4장) & [E079] 수넴 여인의 죽은 아들 소생과 아람 장군 나아만의 요단강 일곱 번 목욕 치유 (왕하 4~5장) & [E080] 도단성을 둘러싼 하늘의 불말과 불병거 및 사마리아 포위 기근 해방과 네 명의 나병환자 (왕하 6~7장)\n• 엘리사 사역 3대 연작 사건의 핵심 시각·신학 고증:\n1. 불수레·불말 승천과 갑절의 영감 (E078, 왕하 2:1-14; 4:1-7): 길갈→벧엘→여리고→요단강까지 스승을 끝까지 따라간 엘리사(P071)가 \"당신의 성령이 하시는 역사가 갑절이나 내게 있게 하소서\"(pî-šənayim, 장자의 두 배 상속 몫 요청, 신 21:17!) 구한 뒤, 불수레와 불말들이 두 사람을 갈라놓고 엘리야가 회오리바람으로 하늘로 올라갈 때 떨어진 엘리야의 털겉옷을 주워 요단강 물을 치며 \"엘리야의 하나님 여호와는 어디 계시니이까\" 갈라 건넘. 이어 선지생도의 아내가 빚주에게 두 아들을 종으로 빼앗길 위기에서 기름 한 그릇 외에는 아무것도 없을 때, 이웃들에게 빈 그릇을 많이 빌려와 문을 닫고 부어 그릇이 다 찰 때까지 기름이 멈추지 않게 하심으로 빚을 다 갚고 모자(母子)의 생계를 구원함.\n2. 수넴 여인과 나아만 장군 치유 (E079, 왕하 4:8-37; 5:1-27; 눅 4:27): 담 위에 작은 방(침상·책상·의자·올리브유 토기 등잔대)을 만들어 엘리사를 섬긴 수넴 여인(P103)이 열사병으로 잃은 아들을 엘리사의 침상에 눕히고 갈멜산까지 나귀를 몰아 달려가 아들을 다시 살려낸 사건, 그리고 포로로 잡혀간 이스라엘 땅의 어린 소녀의 믿음의 한마디로 사마리아에 온 아람 군대장관 나아만(P105)이 문밖으로 나오지도 않고 사자(심부름꾼)를 통해 \"가서 요단강에 몸을 일곱 번 씻으라\" 명한 엘리사의 말에 분노했다가 부하들의 권면으로 교만을 내려놓고 요단강에 일곱 번 몸을 잠가 어린아이의 살같이 깨끗해지고 \"이스라엘 외에는 온 천하에 신이 없는 줄을 아나이다\" 신앙을 고백한 사건.\n3. 도단성의 불말·불병거와 사마리아 네 명의 나병환자 (E080, 왕하 6:8~7:20): 아람 군대가 밤에 도단성을 에워쌌을 때 두려워 떨던 사환을 향해 엘리사가 \"두려워하지 말라 우리와 함께한 자가 그들과 함께한 자보다 많으니라\" 하고 기도하여 사환의 눈을 여시매 불말과 불병거가 산에 가득하여 엘리사를 두른 것(왕하 6:17)을 보게 하고, 눈이 어두워진 아람 군대를 사마리아 한복판으로 인도한 뒤 죽이지 않고 떡과 물을 대접해 돌려보냄으로 도적떼가 다시 오지 못하게 함! 이어 사마리아 포위 대기근 때 엘리사가 \"내일 이맘때에 사마리아 성문에서 고운 밀가루 한 스아를 한 세겔로 매매하리라\" 예언한 대로, 성문 어귀의 네 명의 나병환자가 아람 진영에 갔다가 여호와께서 병거 소리와 말소리를 듣게 하사 다 도망친 빈 진영을 발견하고 \"우리가 이렇게 해서는 아니 되겠도다 오늘날은 아름다운 소식이 있는 날이어늘 우리가 침묵하고 있도다!\"(왕하 7:9 — 복음 전도의 구약적 예화!) 외치며 성에 알려 온 백성을 구원함.",
      "heroImg": "",
      "thumbImg": "",
