      "dossierMd": "■ [E081] 예후의 오므리·아합 왕가 및 바알 숭배 숙청 (왕하 9~10장) & [E082] 여호세바·여호야다의 아기 요아스 성전 6년 은닉·7세 대관식 및 헌금 궤와 스가랴 순교 (왕하 11~12장; 대하 22~24장) & [E083] 요나의 큰 물고기 뱃속 사흘 기도와 니느웨 대회개·박넝쿨 교훈 (욘 1~4장) & [E084] 아모스의 벧엘 공의 선포와 호세아의 고멜 구속 결혼 (암 5; 7장; 호 1~3장)\n• 북왕국 예후 숙청과 남왕국 다윗의 등불 보존 (E081, E082): 북왕국에서는 예후(P061)가 길르앗 라못에서 기름 부음을 받고 병거를 미치게 몰아 나봇의 토지에서 요람(P060)을, 이스르엘 궁전 창가에서 이세벨(P058)을 처단하고 레갑의 아들 여호나답(P265)을 병거에 태워 사마리아 바알 신당을 파쇄함(대영박물관 살만에셀 3세의 검은 오벨리스크 예후 초상 부조 연결).\n• 같은 시각 남유다에서는 아합과 이세벨의 딸인 아달랴(P037)가 왕손들을 다 진멸하려 했으나, 고모 여호세바(P108)와 남편 대제사장 여호야다(P107)가 한 살배기 아기 요아스(P038)를 성전 침실에 6년간 숨겨 기른 뒤 제7년에 백부장들에게 성전 무기고의 다윗 왕의 창과 방패를 나누어 주고 요아스에게 왕관과 율법책을 씌워 즉위시킴으로써 다윗-메시아 언약의 외줄기 생명을 기적적으로 보존함!\n• 주전 8세기 북왕국을 향한 세 선지자(요나·아모스·호세아)의 메시지 (E083, E084): 요나(E083, P078): 원수 나라 앗수르 수도 니느웨로 가라는 명령을 피해 다시스행 배를 탔다가 폭풍 속에서 바다에 던져져 하나님이 예비하신 큰 물고기(dāg gādôl) 뱃속에서 밤낮 사흘 동안 회개 기도를 드리고(\"구원은 여호와께 속하였나이다\", 욘 2:9; 마 12:40 예수님의 십자가 죽음과 3일 부활 표적!), 니느웨 사흘 길을 하루 동안 돌며 외치자 니느웨 왕부터 가축까지 굵은 베옷을 입고 회개하여 재앙을 돌이키심. 성 동편 초막과 박넝쿨(qîqāyôn)을 통해 좌우를 분변하지 못하는 십이만여 명과 가축까지 아끼시는 하나님의 우주적 긍휼을 선포함.\n• 아모스(P076)와 호세아(P074) (E084): 여로보암 2세(P064) 시대의 외형적 번영과 사치(상아 궁·겨울 궁·여름 궁) 이면에서 신 한 켤레 값에 가난한 자를 팔아넘기는 사회 불의를 향해 드고아 목자 아모스가 \"오직 정의를 물같이, 공의를 마르지 않는 강같이 흐르게 할지어다!\"(암 5:24) 다림줄을 들이대고, 호세아는 집을 나가 창기가 된 아내 고멜을 은 열다섯 개와 보리 한 호멜 반(노예 몸값 은 30세겔 상당)으로 다시 사 와서 품음으로써 \"에브라임이여 내가 어찌 너를 놓겠느냐 이스라엘이여 내가 어찌 너를 버리겠느냐... 내 마음이 내 속에서 돌아서서 나의 긍휼이 온전히 불붙듯 하도다\"(호 11:8) 하나님의 끓는 사랑(ḥeseḏ)을 온몸으로 증언함.",
