      "isPillar": false,
      "comparisonKey": null,
      "dossierMd": "■ [E085] 이사야의 성전 보좌·스랍 숯불 소명 (사 6장) & [E086] 아하스 임마누엘 징조와 북이스라엘 멸망(BC 722) (왕하 16~17장; 사 7; 9장) & [E087] 히스기야의 종교개혁·실로암 터널과 산헤립 침공 앞 성전 편지 기도·185,000명 격멸 (왕하 18~20장; 대하 29~32장; 사 36~39장)\n• 웃시야 왕이 죽던 해 이사야 6장 성전 소명 (E085): 52년간 번영했던 웃시야 왕(P040)이 교만하여 성소에서 분향하다 이마에 나병이 발하여 죽던 해(BC 740년경), 청년 이사야(P024)가 성전에서 높이 들린 보좌에 앉으신 주와 여섯 날개(둘로는 얼굴을 가리고 둘로는 발을 가리고 둘로는 날며)로 \"거룩하다 거룩하다 거룩하다 만군의 여호와여 그의 영광이 온 땅에 충만하도다\" 창화하는 스랍(Seraphim)들을 뵙고 \"화로다 나여 망하게 되었도다 나는 입술이 부정한 사람이요...\" 부르짖을 때, 스랍 하나가 부젓가락으로 제단에서 집어 온 핀 숯을 입술에 대어 죄를 사하고 \"내가 누구를 보내며 누가 우리를 위하여 갈꼬\" 물으심에 \"내가 여기 있나이다 나를 보내소서!\"(사 6:8) 응답함.\n• 임마누엘 징조와 북이스라엘 멸망(BC 722), 히스기야와 이사야의 합심 기도 승리 (E086, E087): 북왕국 베가(P069)와 아람 르신의 침공 앞에서 떨던 아하스(P042)에게 윗못 수도 끝에서 \"보라 처녀가 잉태하여 아들을 낳을 것이요 그의 이름을 임마누엘이라 하리라\"(사 7:14; 마 1:23) 징조가 선포되었고, 주전 722년 마지막 왕 호세아(P070) 때 사마리아가 3년 포위 끝에 앗수르에 함락되어 북왕국이 영구 멸망함(E086).\n• 이어 남유다 제13대 히스기야(P043)는 즉위 첫해 첫째 달에 성전 문을 열고 정화하여 남북 온 이스라엘을 초청한 대유월절을 지키고 모세의 놋뱀 '느후스단'을 부수었으며, 주전 701년 앗수르 산헤립(P266)이 유다 46개 성읍(라기스 등)을 점령하고 예루살렘을 포위해 랍사게의 모욕과 협박 편지를 보내왔을 때, 히스기야가 그 편지를 여호와의 성전 앞에 펴 놓고 눈물로 기도하고 선지자 이사야와 함께 하늘을 향하여 부르짖어 기도하매(대하 32:20; 왕하 19:14-19) 그 밤에 여호와의 사자가 나와 앗수르 진영에서 군사 185,000명을 쳐서 예루살렘을 구원하심(E087 — 히스기야 인장 불라·실로암 비문·산헤립 육각기둥 3대 고고학 유물로 완벽 입증!).",
