      "comparisonKey": null,
      "dossierMd": "■ [E088] 요시야 제18년 성전 율법책 발견·여선지자 훌다 검증·벧엘 제단 파괴와 대유월절 (왕하 22~23장; 대하 34~35장) & [E089] 예레미야의 두루마리 소각과 재작성·하박국의 파수대 질문(\"의인은 믿음으로 살리라\")·시위대 뜰 구덩이와 아나돗 밭 매입 (렘 18~19; 28; 32; 36; 38장; 합 2~3장) & [E090] 풀무불('그리 아니하실지라도')·벨사살 분벽 글씨·사자 굴 기도와 에스더의 부림절 대역전 (단 1~6장; 더 1~10장)\n• 요시야의 말씀 대개혁 (E088, BC 622년): 8세에 즉위한 요시야(P046)가 제18년(26세)에 성전을 수리하던 중 대제사장 힐기야(P109)가 발견하고 서기관 사반(P110)이 가져와 읽은 여호와의 율법책(신명기 두루마리)의 말씀을 듣자마자 자기 옷을 찢으며 겸비하여 여선지자 훌다(P097)에게 묻고, 온 백성과 언약을 세운 뒤 예루살렘 성전 안팎의 모든 우상과 산당을 철폐하고 북쪽 벧엘의 여로보암 제단까지 올라가 제단을 헐고 산당을 불사르며 300년 전 유다에서 온 하나님의 사람(P090)의 묘비를 발견해 유골을 보존함(왕상 13:2의 실명 예언이 정확히 300년 만에 성취됨!).\n• 불타지 않는 말씀 두루마리와 시위대 뜰의 소망, 하박국의 믿음 (E089): 하박국(P081)은 파수대에 서서 불의한 시대에 왜 악인이 형통하냐고 질문했다가 \"의인은 그의 믿음으로 말미암아 살리라\"(합 2:4 → 롬 1:17; 갈 3:11; 히 10:38 종교개혁과 복음의 핵심 금구!) 응답을 서판에 새기고 빈 무화과나무와 외양간 앞에서도 구원의 하나님으로 인해 즐거워하는 수금 기도를 드림.\n• 예레미야(P072)와 바룩(P099): 여호야김 왕(P048)이 겨울 궁전 화로 앞에서 예레미야가 구술하고 바룩이 갈대 펜으로 기록한 두루마리를 서기관의 칼로 서너 쪽씩 베어 화로 불에 던져 다 태웠으나, 여호와의 명으로 다른 두루마리를 가져다 처음 책의 모든 말에 그와 같은 많은 말을 더하여 다시 기록함(렘 36:32) → 예루살렘 함락이 임박한 시드기야 제10년 시위대 뜰에 갇히고 구스 내시 에벳멜렉(P100)이 헌 헝겊과 밧줄로 진창 구덩이에서 건져낸 극한 상황 속에서, 예레미야는 사촌 하나멜에게서 바벨론 군대가 점령 중인 고향 아나돗의 밭을 은 십칠 세겔을 저울에 달아 매입하고 매매증서 두 통(봉인본과 열람본)을 토기 항아리에 담아 보관함으로써 \"집과 밭과 포도원을 이 땅에서 다시 사게 되리라\"(렘 32:15) 포로 귀환의 확고한 소망을 행동으로 선포함!\n• 바벨론·페르시아 제국을 이긴 포로기 신앙 (E090): 두라 평지 60규빗 금신상 앞에서 사드락·메삭·아벳느고(P120)가 외친 \"그리 아니하실지라도(וְהֵן לָא, 단 3:18)\" 신앙과 풀무불 속 네 번째 인물의 보호(머리털도 그슬리지 않고 탄 냄새도 없음), 벨사살의 성전 금잔 연회 밤 흰 석회벽(분벽)에 나타난 손가락 글씨(메네 메네 데겔 우바르신, 단 5장), 80대 백발 노총리 다니엘(P025)이 조서에 도장이 찍힌 것을 알고도 예루살렘을 향한 다락방 창문을 열고 하루 세 번 무릎 꿇어 감사 기도하다 사자 굴에 던져졌으나 천사가 사자들의 입을 봉해 상처 하나 없이 나온 사건(단 6장), 그리고 바사 수산 궁에서 왕후 에스더(P117)가 모르드개(P118)의 도전(\"네가 왕후의 자리를 얻은 것이 이때를 위함이 아닌지 누가 알겠느냐\", 더 4:14)을 받고 사흘 밤낮 금식한 뒤 \"죽으면 죽으리이다\" 어전에 나아가 금규를 만지고 하만을 자기가 세운 50규빗 나무에 매달아 유대 민족을 구원한 부림절 대역전까지 완벽히 연결됨.",
