      "isPillar": false,
      "comparisonKey": null,
      "dossierMd": "■ [E121] 가브리엘 천사의 성소 분향단 사가랴 현현과 마리아·사가랴 찬가 (눅 1:5-80) & [E122] 성전 정결례(시므온·안나)와 헤롯 유아 학살·애굽 피신 (마 2:13-23; 눅 2:21-39) & [E123] 12세 소년 예수님의 성전 방문 (눅 2:41-52)\n• 누가복음 1~2장 4대 성탄 찬가(Canticles)와 공간·소품 고증:\n1. 엘리사벳의 축복송(눅 1:42-45) & 마리아의 찬가(Magnificat, 눅 1:46-55): 유대 산골 사가랴의 집에서 두 임산부가 만날 때 복중의 세례 요한(P027)이 성령 충만하여 뛰놀고, 마리아(P028)가 구약 한나의 노래(삼상 2:1-10, E060)와 메아리치는 찬양으로 \"내 영혼이 주를 찬양하며 내 마음이 하나님 내 구주를 기뻐하였음은 그의 여종의 비천함을 돌보셨음이라\" 노래함.\n2. 사가랴의 찬가(Benedictus, 눅 1:67-79): 제비뽑기로 헤롯 성전 성소에 들어가 분향하던 중 금 분향단 우편에 선 가브리엘을 만났던 노제사장 사가랴(P136)가 아기 할례식 날 밀랍 코팅 목판 서판(pinakidion)에 \"그 이름을 요한이라 하라\" 쓰는 순간 입이 열려 \"위로부터 돋는 해가 우리에게 임하여 어둠과 죽음의 그늘에 앉은 자에게 비치고 우리 발을 평강의 길로 인도하시리로다\" 예언함.\n3. 시므온의 찬가(Nunc Dimittis, 눅 2:28-32) & 여선지자 안나(P139) (E122): 출산 40일째 성전 여인의 뜰에서 가난한 자의 정결례 예물인 산비둘기 두 마리(또는 집비둘기 새끼 두 마리, 레 12:8)를 드릴 때, 시므온(P138)이 아기 예수님을 안고 이방을 비추는 빛이요 이스라엘의 영광임을 찬양하고 마리아의 마음을 찌를 칼(십자가)을 예고함.\n4. 12세 성전 문답 (E123, 눅 2:41-52): 유월절 순례 후 사흘 만에 성전 행각에서 랍비들 중에 앉으사 듣기도 하시며 묻기도 하시는 소년 예수님을 찾은 부모에게 \"어찌하여 나를 찾으셨나이까 내가 내 아버지 집에 있어야 될 줄을 알지 못하셨나이까\" 복음서 최초의 친육성 말씀을 남기신 뒤 나사렛에 내려가 부모에게 순종하시며 지혜와 키가 자라가심.",
