      "dossierMd": "■ [E124] 세례 요한의 '하나님의 어린양' 증언과 첫 다섯 제자 부르심 (요 1:19-51) & [E125] 가나 혼인잔치 첫 표적과 제1차 성전 정화 (요 2:1-25) & [E126] 니고데모와의 거듭남 대화(요 3:16)와 세례 요한의 '그는 흥하여야 하겠고' 고백 (요 3:1-36) & [E127] 수가성 야곱의 우물가 사마리아 여인과의 대화 (요 4:1-42)\n• 요한복음 1~4장 '새 창조와 새 성전·새 생명' 대서사 고증: 첫 다섯 제자 연결 사슬 (E124): 세례 요한(P027)의 \"보라 세상 죄를 지고 가는 하나님의 어린양이로다\" → 안드레(P123)와 사도 요한(P122)이 오후 4시(제십시)에 주님과 함께 머묾 → 안드레가 형 시몬 베드로(P029, '게바/베드로' 개명 예고)를 인도 → 주님이 빌립(P124)을 부르심 → 빌립이 나다나엘(바돌로매, P125)에게 \"와서 보라\" 전도하여 무화과나무 아래 기도를 아신 주님께 \"당신은 하나님의 아들이시요 이스라엘의 임금이로소이다\" 고백케 함.\n• 가나 첫 표적과 제1차 성전 정화 (E125): 갈릴리 가나 혼인잔치에서 포도주가 떨어졌을 때 모친 마리아가 하인들에게 \"너희에게 무슨 말씀을 하시든지 그대로 하라\"(요 2:5) 당부하고, 유대 정결례를 따라 두세 통 드는 석회암 돌항아리(1세기 유대 정결법상 부정이 타지 않는 돌그릇 유물 기준!) 여섯 개에 아구까지 채운 물이 연회장이 놀란 최상급 포도주로 변하여 그의 영광을 나타내시매 제자들이 그를 믿음(요 2:11). 이어 유월절 예루살렘 성전에서 노끈으로 채찍을 만드사 양과 소와 비둘기 파는 자들과 돈 바꾸는 자들을 내쫓으시며 \"이 성전을 헐라 내가 사흘 동안에 일으키리라... 그러나 예수는 성전된 자기 육체를 가리켜 말씀하신 것이라\"(요 2:19, 21) 선언하심.\n• ★ [필수 사건 분리 기준] 성전 정화 사건 2회 완벽 구별표: 발생 시기: 공생애 시작 직후 첫 번째 유월절 (가나 혼인잔치 직후) (공생애 마지막 주간(수난주간 월요일), 나귀 입성 이튿날)\n• 핵심 말씀: \"이것을 여기서 가져가라 내 아버지의 집으로 장사하는 집(oikon emporiou)을 만들지 말라\" & \"이 성전을 헐라 내가 사흘 동안에 일으키리라\" (\"내 집은 만민이 기도하는 집이라 칭함을 받으리라(사 56:7) 하였거늘 너희는 강도의 소굴(렘 7:11)을 만들었도다\")\n• 니고데모 밤 대화(E126)와 수가성 정오 우물가 대화(E127)의 극적 대조: 요 3장(E126)의 니고데모(P144): 유대인 남성·바리새인·산헤드린 관원·도덕적 존경 대상·밤에 찾아옴 → \"사람이 물과 성령으로 나지 아니하면... 모세가 광야에서 뱀을 든 것같이 인자도 들려야 하리니... 하나님이 세상을 이처럼 사랑하사 독생자를 주셨으니\"(요 3:16).\n• 요 4장(E127)의 수가성 여인(P146): 사마리아인 여성·남편 다섯 있었던 소외자·대낮 정오(제육시)에 야곱의 우물가에서 만남 → \"내가 주는 물을 마시는 자는 영원히 목마르지 아니하리니... 아버지께 참되게 예배하는 자들은 영과 진리로 예배할 때가 오나니\" → 물동이를 버려두고 달려가 온 동네를 구원케 한 전도자가 됨!",
