      "dossierMd": "■ [E128] 왕의 신하 아들 말씀 치유(제2표적)와 나사렛 회당 설교 (요 4:46-54; 눅 4:16-30) & [E129] 게네사렛 호수 깊은 데 그물을 내린 만선 소명 (눅 5:1-11) & [E130] 가버나움 안식일 치유와 새벽 기도 (막 1:21-39) & [E131] 나병환자 터치 치유와 지붕을 뚫고 내린 중풍병자 사죄·치유 (막 1:40~2:12) & [E132] 가버나움 세관 마태 부르심과 세리·죄인 잔치 (마 9:9-17)\n• ★ [필수 사건 분리 기준] 갈릴리 호수 만선(물고기 잡이) 기적 2회 완벽 구별표: 발생 시기: 공생애 초기, 베드로·안드레·야고보·요한을 전임 제자로 부르실 때 (십자가 부활 후, 일곱 제자가 갈릴리 디베랴 호수에서 고기 잡을 때)\n• 주님의 위치와 말씀: 예수님이 시몬의 배에 오르사 말씀을 가르치신 후 \"깊은 데로 가서 그물을 내려 고기를 잡으라\" (예수님이 바닷가에 서셔서 \"얘들아 너희에게 고기가 있느냐... 그물을 배 오른편에 던지라 그리하면 잡으리라\")\n• 그물 상태와 결과: 고기를 에운 것이 심히 많아 그물이 찢어지는지라 두 배에 채우매 잠기게 됨 → 베드로가 무릎 아래 엎드려 \"주여 나를 떠나소서 나는 죄인이로소이다\" → \"무서워하지 말라 이제 후로는 네가 사람을 취하리라\" (큰 물고기가 백쉰세 마리(153마리)나 되나 이같이 많으되 그물이 찢어지지 아니하였더라 → 요한이 \"주님이시라!\" 알아보고 베드로가 겉옷을 두르고 바다로 뛰어내려와 숯불 조반과 세 번 사랑 확인(\"내 양을 먹이라\")으로 이어짐)",
