      "dossierMd": "■ [E133] 예루살렘 베데스다 못가의 38년 된 병자 치유 (요 5:1-47) & [E134] 안식일 밀 이삭·손 마른 자 치유 (마 12:1-50) & [E135] 가버나움 백부장 하인 말씀 치유와 나인성 과부 외아들 부활 (마 8:5-13; 눅 7:1-17)\n• 생명과 안식일의 주인이신 그리스도: 베데스다 38년 병자 (E133, P337): 예루살렘 양문 곁 다섯 행각이 있는 베데스다 연못(19세기 말 발굴된 1세기 이중 석조 저수조와 5개 주랑 유적)에서 38년 동안 누워 있던 병자에게 \"일어나 네 자리를 들고 걸어가라!\" 명하시고, 안식일 규정을 들어 박해하는 유대인들에게 \"내 아버지께서 이제까지 일하시니 나도 일한다... 너희가 성경에서 영생을 얻는 줄 생각하고 성경을 연구하거니와 이 성경이 곧 내게 대하여 증언하는 것이니라\"(요 5:17, 39) 선언하심.\n• 가버나움 백부장과 나인성 과부 (E135): 이방인 로마 백부장(P148)의 \"다만 말씀으로만 하옵소서\" 믿음으로 하인을 고치신 직후, 갈릴리 나인성 성문 밖으로 나오는 과부(P274)의 외아들 장례 행렬을 마주치사 과부를 보시고 불쌍히 여기사 \"울지 말라\" 하시며 유대 정결법상 접촉이 금지된 관(개방형 나무 들것 soros)에 친히 손을 대시어 메고 가던 자들을 멈추게 하시고 \"청년아 내가 네게 말하노니 일어나라!\" 살려 어머니에게 주심(복음서 3대 죽은 자 부활 기적[① 나인성 과부 외아들 눅 7장, ② 야이로의 12살 딸 막 5장, ③ 죽은 지 나흘 된 베다니 나사로 요 11장] 중 첫 번째!).",
