      "dossierMd": "■ [E136] 세례 요한의 옥중 질문 답변·'수고하고 무거운 짐 진 자들아'(마 11:28) 초청 및 바리새인 시몬의 집에서 눈물로 발을 적신 여인 (마 11:2-30; 눅 7:18-50)\n• ★ [필수 사건 분리 기준] 복음서 내 '향유 옥합 부음' 사건 2회 완벽 구별표: 시기 및 장소: 갈릴리 중기 사역, 갈릴리의 한 바리새인 시몬의 집 (공생애 마지막 유월절 엿새 전(수난 직전), 예루살렘 인근 베다니 나병환자 시몬의 집)\n• 행위자 및 행동: 그 동네에 죄를 지은 한 여자(P341)가 예수님 뒤로 발 곁에 서서 울며 눈물로 발을 적시고 머리털로 닦고 입 맞추고 발에 향유를 부음 (나사로의 누이 베다니 마리아(P142)가 삼백 데나리온 가치의 순전한 나드 한 근 옥합을 깨뜨려 예수님의 머리와 발에 붓고 머리털로 발을 닦음)\n• 비난자 및 주님의 선언: 집주인 바리새인 시몬이 속으로 \"선지자라면 이 여자가 죄인인 줄 알았으리라\" 비난 → 500데나리온과 50데나리온 두 빚진 자 비유 후 \"이 여자의 많은 죄가 사하여졌도다 이는 그의 사랑함이 많음이라... 네 믿음이 너를 구원하였으니 평안히 가라\" (가룟 유다(P131)와 제자들이 \"어찌하여 허비하느냐 삼백 데나리온에 팔아 가난한 자들에게 주었겠도다\" 비난 → \"그를 가만두라 그가 내 장례할 날을 위하여 이를 간직하게 하라... 온 천하에 복음이 전파되는 곳에는 이 여자가 행한 일도 말하여 그를 기억하리라\")",
