      "dossierMd": "■ [E137] 갈릴리 호숫가 천국 7대 비유 (마 13장) · [E138] 광풍을 잠잠케 하심과 거라사 군대 귀신 축출 (막 4:35~5:20) · [E139] 12년 혈루증 여인과 야이로의 12살 딸 소생(\"달리다굼\", 막 5:21-43) · [E140] 12제자 파송과 세례 요한 순교 (마 10; 14장) · [E141] 수로보니게 여인의 큰 믿음 (마 15:21-28) · [E142] 데가볼리 '에바다' 치유와 칠병이어 급식 (막 7:31~8:26) · [E143] 변화산 아래 귀신 들린 아이 치유와 물고기 입의 한 세겔 성전세 (마 17:14-27) · [E144] 일만 달란트 탕감 비유와 70인 전도대 파송 (마 18장; 눅 10장)\n• 자연·질병·귀신·죽음을 다스리시는 메시아 권능: 광풍 제압과 거라사 회복 (E138): 배 고물에서 베개를 베고 주무시다 제자들의 부르짖음에 일어나 바람을 꾸짖으시며 바다더러 \"잠잠하라 고요하라(Siōpa, pephimōso)\" 하시니 바람이 그치고 아주 잔잔하여짐 → 건너편 거라사(가다라)에서 무덤 사이에 거하던 군대 귀신 들린 자(P339)를 온전케 하사 옷을 입히고 데가볼리 열 성읍의 첫 이방인 복음 전도자로 파송하심.\n• 혈루증 여인과 야이로의 딸 (E139): 군중이 에워싸 밀치는 가운데서도 믿음으로 예수님의 겉옷 가의 술(kraspedon, 치치트)을 만진 12년 혈루증 여인(P273)에게서 능력이 나간 줄 아시고 그녀를 두려움에서 불러내어 \"딸아 네 믿음이 너를 구원하였으니 평안히 가라\" 공개적으로 정결함과 구원을 선포하시고, 이어 죽었다고 통곡하는 야이로의 집에 들어가 소녀의 손을 잡고 \"달리다굼!\" 말씀으로 일으키심.",
