      "summary": "초막절 실로암 물 붓기 예식 날 \"나를 믿는 자는 그 배에서 생수의 강이 흘러나리라\"(성령 예고, 요 7:37-39) 외치시고, 돌을 든 고발자들 앞에서 땅에 손가락으로 쓰시며 \"죄 없는 자가 먼저 돌로 치라\" 여인을 살리신 후 초막절 대형 금 촛대 앞에서 \"나는 세상의 빛이니\" 선언하신 사건",
