      "dossierMd": "■ [E145] 초막절 성전 '생수의 강'·'세상의 빛' 선언과 간음하다 잡힌 여인 용서 (요 7~8장) · [E146] 실로암 날 때부터 맹인 치유와 선한 목자 강론 (요 9~10장) · [E147] 선한 사마리아인 비유와 베다니 마르다·마리아 방문 (눅 10:25-42) · [E148] 돌아온 탕자(잃은 양·드라크마·두 아들, 눅 15장)와 바리새인·세리의 기도 비유 (눅 18장) · [E149] 어린아이 축복·부자 청년 관원·'많은 사람의 대속물'(막 10:45) 선언 (마 19~20장; 막 10장) · [E150] 베다니 나사로 부활 표적(\"나는 부활이요 생명이니... 나사로야 나오라!\", 요 11장) · [E151] 여리고 바디매오·삭개오 회심과 베다니 마리아의 순전한 나드 옥합 헌신 (막 10:46-52; 눅 19:1-10; 요 12:1-11)\n• 초막절 2대 성전 의식(물 붓기 & 대형 금 촛대 점등)과 예수님의 선언 (E145): 제사장들이 실로암 못에서 금 주전자에 물을 길어 와 번제단에 부으며 구원의 우물을 노래하던 초막절 끝날 곧 큰 날에, 예수님께서 서서 외쳐 \"누구든지 목마르거든 내게로 와서 마시라 나를 믿는 자는 성경에 이름과 같이 그 배에서 생수의 강이 흘러나리라\"(요 7:37-38, 성령 강림 예고!) 선포하시고, 밤마다 여인의 뜰을 환히 밝히던 4개의 거대한 초막절 금 촛대 앞에서 \"나는 세상의 빛이니 나를 따르는 자는 어둠에 다니지 아니하고 생명의 빛을 얻으리라\"(요 8:12) 선언하심.\n• 베다니 나사로 부활 표적 (E150, 요 11:1-57): 나사로가 병들었다는 소식을 듣고도 하나님의 영광을 위하여 이틀을 더 유하신 후 베다니에 오셔서, 마르다에게 \"나는 부활이요 생명이니 나를 믿는 자는 죽어도 살겠고 무릇 살아서 나를 믿는 자는 영원히 죽지 아니하리니 이것을 네가 믿느냐\"(요 11:25-26) 선포하시고 마리아와 함께 눈물을 흘리신(요 11:35) 뒤, 죽은 지 나흘이 되어 냄새가 나는 바위 굴무덤 돌을 옮겨 놓게 하시고 하늘을 우러러 감사 기도하신 후 큰 소리로 \"나사로야 나오라!\" 부르시매 죽었던 자가 수족을 베로 동인 채로 걸어 나옴.",
