      "dossierMd": "■ [E152] 수난주간 입성~감람산 강화 · [E153] 겟세마네 체포·가야바 야간 재판·베드로 세 번 부인 · [E154] 빌라도·헤롯 재판과 바라바 석방·비아 돌로로사 · [E155] 골고다 십자가 가상칠언·성소 휘장 찢어짐·새 무덤 장사 · [E156] 부활 주일 새벽 빈 무덤(\"랍오니!\")·엠마오 두 제자·다락방 현현 · [E157] 도마의 신성 고백(\"나의 주님이시요 나의 하나님이시니이다\")·디베랴 호수 숯불 조반 베드로 회복(\"내 양을 먹이라\")·지상명령과 감람산 승천\n• 수난주간~부활·승천 일자별 6대 사건 연속 타임라인 완비:\n1. 주일~화요일 (E152): 나귀 새끼를 타신 예루살렘 입성과 예루살렘을 보시며 우심(눅 19:41) → 무화과나무와 제2차 성전 정화 → 성전 권위·세금·부활·가장 큰 계명 논쟁과 두 렙돈 과부 칭찬 → 감람산 종말 강화(열 처녀·달란트·양과 염소, 마 24~25장).\n2. 목요일 밤~금요일 새벽 (E153, cf. E028): 다락방 세족식·성찬 제정·고별 강화(요 13~17장)와 겟세마네 피땀 기도 → 유다의 입맞춤 배반과 체포(말고의 오른쪽 귀 치유) → 안나스와 가야바(P200) 관저 야간 산헤드린 재판(\"내가 그니라 인자가 권능의 우편에 앉은 것과 하늘 구름을 타고 오는 것을 너희가 보리라\")과 안뜰 숯불(anthrakia) 앞 베드로의 세 번 부인 및 주께서 돌이켜 베드로를 보시매(눅 22:61) 밖에 나가 심히 통곡함.\n3. 금요일 오전 (E154): 본디오 빌라도(P199) 법정과 헤롯 안디바(P197) 심문, 빌라도 아내(P343)의 꿈 경고, 바라바(P280) 석방, 채찍질과 가시관(\"보라 이 사람이로다\"), 빌라도의 손 씻음, 구레네 시몬(P151)이 대신 진 십자가 가로목과 골고다 길.\n4. 금요일 오전 9시~일몰 전 (E155): 골고다 십자가 못 박히심과 가상칠언, 회개한 강도(P277)의 낙원 약속, 제6시~제9시 흑암과 \"엘리 엘리 라마 사박다니\"·\"다 이루었다(Τετέλεσται)\", 성소 휘장이 위로부터 아래까지 둘로 찢어짐, 로마 백부장(P278)의 신앙고백, 창에 찔린 옆구리의 피와 물, 아리마대 요셉(P145)과 니고데모(P144)의 몰약·침향 백 근과 세마포 새 무덤 장사.\n5. 부활 주일 새벽~밤 (E156): 안식 후 첫날 새벽 빈 무덤과 천사의 선언 → 베드로와 요한의 달음질 → 무덤 밖에서 울던 막달라 마리아(P140)에게 \"마리아야!\"—\"랍오니!\" 첫 부활 현현 → 엠마오로 가던 글로바와 두 제자(P279)에게 성경을 풀어 주시고 식탁에서 떡을 떼실 때 눈이 밝아짐 → 그 밤 다락방 제자들에게 나타나사 \"너희에게 평강이 있을지어다\" 손과 옆구리를 보이시고 구운 생선 한 토막을 잡수시며 숨을 내쉬어 \"성령을 받으라\" 명하심.\n6. 부활 후 여드레~40일 승천 (E157): 여드레 후 다락방에 다시 나타나사 도마(P127)로부터 \"나의 주님이시요 나의 하나님이시니이다!\"(요 20:28) 신성 고백을 받으심 → 갈릴리 디베랴 호수에서 153마리 만선 기적을 일으키시고 해변에 피우신 숯불(anthrakia) 조반 후 시몬 베드로에게 세 번 \"요한의 아들 시몬아 네가 나를 사랑하느냐... 내 어린양을 먹이라 / 내 양을 치라 / 내 양을 먹이라\"(요 21:15-17) 사명을 회복시키심 → 갈릴리 산에서 오백여 형제(고전 15:6)와 열한 제자에게 \"하늘과 땅의 모든 권세를 내게 주셨으니 그러므로 너희는 가서 모든 민족을 제자로 삼아 아버지와 아들과 성령의 이름으로 세례를 베풀고 내가 너희에게 분부한 모든 것을 가르쳐 지키게 하라 볼지어다 내가 세상 끝날까지 너희와 항상 함께 있으리라\"(마 28:18-20) 지상명령을 주시고 예루살렘 동편 감람산에서 두 손을 들어 축복하시며 구름을 타고 승천하심(행 1:8-11).",
