      "summary": "여인들과 예수님의 모친 마리아와 아우들과 사도들이 마음을 같이하여 오로지 기도에 힘쓴 결과 임한 오순절 성령 강림과, 요엘서·시편을 인용한 베드로의 담대한 부활 설교로 하루에 3, 000명이 세례를 받고 사도의 가르침·교제·떡 뗌·기도에 전혀 힘쓴 원형 교회의 탄생",
