      "dossierMd": "■ [E158] 마가의 다락방 맛디아 사도 보선과 오순절 성령 강림·베드로 첫 설교 3천 명 회심·유무상통 공동체 탄생 (행 1:12~2:47)\n• 핵심 참여 인물: P029 베드로, P122 요한, P028 모친 마리아, P133 주의 형제 야고보, P132 맛디아, P345 요셉 바사바(유스도).\n• 사건 재구성: 감람원으로부터 예루살렘에 돌아와 마가의 다락방에서 여인들과 예수의 어머니 마리아와 예수의 아우들과 더불어 마음을 같이하여 오로지 기도에 힘쓰며 가룟 유다의 빈자리에 부활의 증인 맛디아(P132)를 제비뽑아 열두 사도의 수를 채움 → 오순절 날 급하고 강한 바람 같은 소리와 불의 혀처럼 갈라지는 성령 강림 후, 비웃는 이들을 향해 베드로가 열한 사도와 함께 서서 소리를 높여 요엘 2:28-32(말세 성령 강림)과 시편 16편·110편(다윗이 미리 본 그리스도의 부활과 보좌 우편 승귀)을 풀어 \"너희가 십자가에 못 박은 이 예수를 하나님이 주와 그리스도가 되게 하셨느니라!\"(행 2:36) 선포하매, 마음에 찔려 \"형제들아 우리가 어찌할꼬\" 묻는 무리에게 회개와 세례를 명하여 그날에 신도의 수가 삼천이나 더하고 날마다 마음을 같이하여 성전에 모이기를 힘쓰고 집에서 떡을 떼며 기쁨과 순전한 마음으로 음식을 먹고 구원받는 사람을 날마다 더하시는 교회가 탄생함.",
