      "isPillar": false,
      "comparisonKey": null,
      "dossierMd": "■ [E159] 성전 미문 나면서 못 걷던 이의 치유와 산헤드린 앞 담대한 선포·바나바의 헌신과 아나니아·삽비라 사건 (행 3:1~5:16) & [E160] 사도들의 두 번째 투옥(천사 옥문 개방·가말리엘 신중론)과 일곱 집사 선출 (행 5:17~6:7) & [E161] 스데반 집사의 구속사 대설교와 보좌 우편에 서신 예수님 현현·첫 순교 (행 6:8~8:3)\n• 예루살렘 초대교회의 외적 박해 극복과 내적 거룩·조직 성숙: 성전 미문과 공회 법정 (E159): 제9시(오후 3시) 기도 시간에 성전 미문(코린트 청동 니카노르 문) 앞에서 구걸하던 나면서 못 걷던 이를 베드로(P029)와 요한(P122)이 주목하여 \"은과 금은 내게 없거니와 내게 있는 이것을 네게 주노니 나사렛 예수 그리스도의 이름으로 일어나 걸으라!\" 오른손을 잡아 일으키매 발과 발목이 곧 힘을 얻어 걷기도 하고 뛰기도 하며 하나님을 찬송함 → 체포되어 가야바·안나스 공회 앞에 섰을 때도 \"다른 이로써는 구원을 받을 수 없나니 천하 사람 중에 구원을 받을 만한 다른 이름을 우리에게 주신 일이 없음이라... 하나님 앞에서 너희의 말을 듣는 것이 하나님의 말씀을 듣는 것보다 옳은가 판단하라 우리는 보고 들은 것을 말하지 아니할 수 없다\"(행 4:12, 19-20) 담대히 외침.\n• 가말리엘의 신중론과 일곱 집사 세움 (E160): 사도들이 능욕 받는 일에 합당한 자로 여기심을 기뻐하며 날마다 성전과 집에서 예수는 그리스도라 가르치기와 전도하기를 그치지 아니하고(행 5:41-42), 구제 문제로 원망이 생기자 사도들은 \"기도하는 일과 말씀 사역에 힘쓰리라\" 선언하고 성령과 지혜가 충만한 일곱 집사(P152 스데반, P153 빌립, P344 브로고로·니가노르·디몬·바메나·니골라)를 안수해 세우니 하나님의 말씀이 점점 왕성하여 허다한 제사장의 무리도 이 도에 복종함(행 6:7).\n• 스데반의 구속사 설교와 첫 순교 (E161): 공회 앞에서 천사의 얼굴과 같이 빛나며 아브라함·요셉·모세·성막·솔로몬 성전을 관통해 하나님의 임재는 성전 건물에 갇히지 않으며 의인이신 예수 그리스도에게서 완성됨을 논증한 스데반이, 성령이 충만하여 하늘을 우러러 하나님 우편에 서신 예수님을 보고 증인들이 옷을 청년 사울(P030)의 발 앞에 두는 가운데 돌에 맞으면서도 무릎을 꿇고 \"주 예수여 내 영혼을 받으시옵소서... 주여 이 죄를 그들에게 돌리지 마옵소서\" 기도하고 잠듦.",
