      "comparisonKey": null,
      "dossierMd": "■ [E162] 전도자 빌립의 사마리아 성 대부흥과 에티오피아 내시 세례 (행 8:4-40) & [E163] 다메섹 사울의 회심과 아나니아 안수·바나바 중재 (행 9:1-31) & [E164] 베드로의 욥바 다비다 소생·보자기 환상과 가이사랴 고넬료 가정의 '이방인 오순절' (행 9:32~11:18) & [E165] 안디옥 이방인 교회 설립('그리스도인' 호칭)과 사울·바나바 동역 (행 11:19-30) & [E166] 헤롯 아그립바 1세의 박해(야고보 순교)와 베드로의 옥중 천사 구출·로데의 기쁨 (행 12:1-24)\n• 사도행전 1:8(\"예루살렘과 온 유대와 사마리아와 땅끝까지\")의 단계적 돌파: 사마리아와 에티오피아 내시 (E162): 스데반 박해로 흩어진 빌립 집사(P153)가 사마리아 성에 내려가 그리스도를 전파하여 큰 기쁨이 임하게 하고, 성령의 지시로 가사 광야 길로 내려가 수레 위에서 이사야 53:7-8(\"그가 도살자에게로 가는 양과 같이 끌려갔고...\") 두루마리를 읽던 에티오피아 간다게 여왕의 국고 총무 내시(P282)에게 예수를 가르쳐 길가 물에서 세례를 베풂으로써 아프리카 대륙으로 복음이 전해짐.\n• 욥바 다비다 소생과 가이사랴 고넬료 가정의 이방인 오순절 (E164): 베드로(P029)가 욥바에서 과부들을 위해 속옷·겉옷을 짓던 여제자 다비다(도르가, P179)를 기도로 살리고 바닷가 무두장이 시몬(P283)의 집 지붕에서 제6시(정오)에 기도하다가 하늘에서 내려온 큰 보자기 환상(\"하나님께서 깨끗하게 하신 것을 네가 속되다 하지 말라\", 세 번 반복)을 본 직후, 가이사랴 이달리야 부대 백부장 고넬료(P154)가 보낸 사람들을 따라가 그 집에 모인 무할례 이방인들에게 예수 그리스도의 화평의 복음과 부활을 선포할 때 말씀 듣는 모든 사람에게 성령이 내려 물세례를 베풀고 이방인 교회의 문을 공식 개방함!\n• 안디옥 교회의 탄생과 '그리스도인' (E165): 구브로와 구레네 몇 사람이 수리아 안디옥에 이르러 헬라인에게도 주 예수를 전파하니 주의 손이 함께하사 수많은 사람이 믿고 돌아옴 → 예루살렘 교회가 파송한 바나바(P156)가 하나님의 은혜를 보고 기뻐하며 길리기아 다소에 가서 사울(P030)을 찾아 데리고 와 둘이 교회에 일 년간 모여 있어 큰 무리를 가르쳤고 제자들이 안디옥에서 비로소 '그리스도인'(Christianous)이라 일컬음을 받음(행 11:26).",
