      "dossierMd": "■ [E300] 새 하늘과 새 땅·거룩한 성 새 예루살렘 강림과 생명수 강·생명나무 회복 및 \"아멘 주 예수여 오시옵소서!\" 대단원 (계 21:1~22:21)\n1. 구속사 300대 사건(E001~E300)의 완벽한 수미쌍관(Inclusio) 대조표: 창세기 1~3장 (E001~E003: 시작과 상실): 요한계시록 21~22장 (E300: 구속의 완성!)\n• \"태초에 하나님이 천지를 창조하시니라\" (창 1:1): \"내가 새 하늘과 새 땅을 보니 처음 하늘과 처음 땅이 없어졌고\" (계 21:1)\n• 해와 달 광명체를 만들어 밤과 낮을 주관하게 하심 (창 1:16): \"성 안에 성전을 내가 보지 못하였으니 이는 주 하나님 곧 전능하신 이와 및 어린양이 그 성전이심이라 그 성은 해나 달의 비침이 쓸데없으니 이는 하나님의 영광이 비치고 어린양이 그 등불이 되심이라... 거기에는 밤이 없겠고\" (계 21:22-25)\n• 불순종으로 말미암아 땅이 저주를 받고 슬픔과 죽음·눈물이 시작됨 (창 3:16-19): \"보라 하나님의 장막이 사람들과 함께 있으매... 모든 눈물을 그 눈에서 닦아 주시니 다시는 사망이 없고 애통하는 것이나 곡하는 것이나 아픈 것이 다시 있지 아니하리니... 다시 저주가 없으며\" (계 21:3-4; 22:3)\n• 에덴에서 쫓겨나 생명나무의 길이 막힘 (창 3:22-24): \"또 그가 수정 같이 맑은 생명수의 강을 내게 보이니 하나님과 및 어린양의 보좌로부터 나와서 길 가운데로 흐르더라 강 좌우에 생명나무가 있어 열두 가지 열매를 맺되 달마다 그 열매를 맺고 그 나무 잎사귀들은 만국을 치료하기 위하여 있더라\" (계 22:1-2)\n2. 성경 66권의 마지막 약속과 교회의 화답 (계 22:20-21): \"이것들을 증언하신 이가 이르시되 내가 진실로 속히 오리라 하시거늘 아멘 주 예수여 오시옵소서(마라나타)! 주 예수의 은혜가 모든 자들에게 있을지어다 아멘.\"",
